/* KHBD Âm nhạc Lớp 2 KNTT — Bút Xanh, tích hợp NLS+AI */
window.KHO_DATA_L2_AMNHAC = [
{"lop":2,"mon":"Âm nhạc","tuan":1,"tiet":1,"bai":"Chủ đề 1: Sắc màu âm thanh — Học hát: Dàn nhạc trong vườn (Nhạc và lời: Tô Đông Hải)","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Hát đúng giai điệu, thuộc lời ca bài Dàn nhạc trong vườn; thể hiện được tính chất nhịp nhàng của nhịp 3/4.\n- Bước đầu hình thành kĩ năng hát: hát rõ lời, ngồi/đứng đúng tư thế, biết lấy hơi đầu câu.\n- Biết hát kết hợp gõ đệm theo phách.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động tập luyện, mạnh dạn thể hiện bài hát/bài đọc nhạc; tự điều chỉnh khi hát/gõ chưa đúng.\n- Giao tiếp và hợp tác: Biết hát, gõ đệm, vận động theo nhóm; lắng nghe và phối hợp nhịp nhàng cùng bạn.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm hoặc ý tưởng biểu diễn đơn giản.\n3. Phẩm chất\n- Nhân ái, chăm chỉ: Thêm gắn bó, yêu quý thiên nhiên, loài vật.\n- Chăm chỉ: Tích cực tham gia các hoạt động ca hát, đọc nhạc, trò chơi âm nhạc.\n- Yêu thích môn Âm nhạc; cảm nhận được vẻ đẹp của âm thanh.\n4. Tích hợp\n- Năng lực số 1.1 CB1 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS nghe bản thu mẫu và hát đúng lời, đúng cao độ bài “Dàn nhạc trong vườn”.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ cơ bản (thanh phách, song loan, trống con, ma-ra-cát).\n- HS: SGK Âm nhạc 2 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ cơ bản (thanh phách, song loan) nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"Mục tiêu: Tạo tâm thế vui vẻ, dẫn dắt vào bài hát.\n- GV ổn định lớp, hỏi cảm nhận của các em khi lên lớp 2.\n- GV tổ chức trò chơi \"Em yêu thế giới muôn loài\": chia lớp 4 nhóm, mỗi nhóm nhận 1 tranh con vật (vịt, gà, mèo, chim); GV hỏi theo tiết tấu \"Bạn thích con gì?\", các nhóm trả lời theo tiết tấu.\n- GV dẫn dắt: Trong vườn có nhiều loài chim cùng cất tiếng hót tạo thành một \"dàn nhạc\" rất hay.","hs":"- HS ngồi ngay ngắn, lớp trưởng báo cáo sĩ số.\n- Các nhóm nhận tranh, lắng nghe và trả lời theo tiết tấu.\n- HS lắng nghe, ghi tên bài."},{"ten":"B. KHÁM PHÁ - HỌC HÁT (15 phút)","gv":"Mục tiêu: HS hát đúng giai điệu, lời ca bài Dàn nhạc trong vườn.\n- GV giới thiệu bài hát nói về một khu vườn thiên nhiên với tiếng hót của các loài chim (cu gáy, vàng anh, chích choè) tạo thành dàn nhạc trong vườn.\n- GV hát mẫu (hoặc mở file), hỏi cảm nhận ban đầu của HS.\n- GV hướng dẫn đọc lời ca theo tiết tấu, chia bài thành 4 câu hát.\n- Dạy hát nối tiếp từng câu; nhắc HS hát ngân đúng, lấy hơi trước mỗi câu.\n- Cho HS hát cả bài với nhiều hình thức: tập thể, tổ, cá nhân.","hs":"- HS lắng nghe, nêu cảm nhận: bài hát vui tươi, nhịp nhàng.\n- HS đọc lời ca, học hát từng câu theo hướng dẫn.\n- HS hát cả bài, thể hiện sắc thái nhịp nhàng của nhịp 3/4."},{"ten":"C. THỰC HÀNH - LUYỆN TẬP (10 phút)","gv":"Mục tiêu: HS hát kết hợp gõ đệm theo phách.\n- GV hướng dẫn cách gõ đệm theo phách: gõ vào bông hoa màu đỏ (phách mạnh) và màu vàng (phách nhẹ).\n- Cả lớp hát kết hợp gõ đệm theo phách.\n- Mời dãy, tổ, cá nhân thực hiện; GV nhận xét, sửa sai.","hs":"- HS quan sát, thực hiện gõ đệm theo phách.\n- Các tổ, cá nhân xung phong thể hiện."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở bản thu mẫu bài “Dàn nhạc trong vườn” lấy từ học liệu điện tử của bộ sách hoặc kênh chính thức của nhà xuất bản, phóng màn hình để cả lớp nhìn thấy tên bài hát, chỉ cho HS dòng ghi tác giả “Nhạc và lời: Tô Đông Hải”; GV mở từng câu, tạm dừng cho HS nghe kĩ rồi hát theo, câu nào HS hát chênh cao độ thì GV mở lại đúng câu đó.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV dùng điện thoại thu âm phần hát bài “Dàn nhạc trong vườn” của cả lớp rồi mở lại ngay cho HS nghe; HS chỉ ra chỗ mình hát to quá, nhỏ quá hoặc sai lời — nghe lại giọng của chính mình là điều hát chay không có được. GV thao tác thiết bị, HS nghe và nhận xét.\n⚠ (Miền 4: An toàn) Bản thu bài “Dàn nhạc trong vườn” chỉ lấy từ học liệu của bộ sách hoặc kênh chính thức, không tải nhạc từ trang lạ vì có thể sai lời, sai nhạc và kèm quảng cáo không phù hợp; giới thiệu bài hát phải nói rõ tên tác giả; mở loa vừa đủ nghe, không để loa sát tai HS.","hs":"- HS nghe bản thu mẫu và hát đúng lời, đúng cao độ bài “Dàn nhạc trong vườn”.\n- HS nói được tên bài hát cùng tên tác giả; nghe lại bản thu của lớp và chỉ ra một chỗ cần sửa."},{"ten":"E. CỦNG CỐ - DẶN DÒ (2 phút)","gv":"- GV hệ thống lại nội dung tiết học, nhận xét tiết học (khen ngợi, nhắc nhở).\n- GV dặn HS về nhà ôn lại bài, tập biểu diễn cho người thân nghe, chuẩn bị bài tiết sau và làm bài trong vở bài tập (nếu có).","hs":"- HS lắng nghe, ghi nhớ.\n- HS hát/đọc nhạc lại một lần để kết thúc tiết học vui vẻ."}],"hotro":"","hoanhap":"","status":"checked","source":"KHBD Âm nhạc 2 KNTT — Bút Xanh (biên soạn tích hợp NLS + AI)"},
{"lop":2,"mon":"Âm nhạc","tuan":2,"tiet":2,"bai":"Chủ đề 1: Sắc màu âm thanh — Ôn tập bài hát: Dàn nhạc trong vườn; Nghe câu chuyện: Ước mơ của bạn Đô","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Hát được giai điệu, đúng lời ca bài Dàn nhạc trong vườn; hát kết hợp vỗ tay theo nhịp, phách và vận động cơ thể.\n- Nhớ và hiểu được nội dung câu chuyện Ước mơ của bạn Đô; bước đầu nhận biết nhạc cụ kèn đồng.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động tập luyện, mạnh dạn thể hiện bài hát/bài đọc nhạc; tự điều chỉnh khi hát/gõ chưa đúng.\n- Giao tiếp và hợp tác: Biết hát, gõ đệm, vận động theo nhóm; lắng nghe và phối hợp nhịp nhàng cùng bạn.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm hoặc ý tưởng biểu diễn đơn giản.\n3. Phẩm chất\n- Chăm chỉ, nhân ái: Biết mơ ước và cố gắng thực hiện ước mơ đẹp.\n- Chăm chỉ: Tích cực tham gia các hoạt động ca hát, đọc nhạc, trò chơi âm nhạc.\n- Yêu thích môn Âm nhạc; cảm nhận được vẻ đẹp của âm thanh.\n4. Tích hợp\n- Năng lực số 1.1 CB1 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS nêu được đặc điểm nổi bật của “Ước mơ của bạn Đô” nhờ quan sát tư liệu số và nghe bản thu.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ cơ bản (thanh phách, song loan, trống con, ma-ra-cát).\n- HS: SGK Âm nhạc 2 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ cơ bản (thanh phách, song loan) nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"- GV cho HS đọc và vỗ tay theo hình tiết tấu (vỗ mạnh vào số 1, vỗ nhẹ báo số 2, 3).\n- Có thể chia 3 nhóm vỗ tay nối tiếp.","hs":"- HS đếm số, vỗ tay theo tiết tấu; các nhóm thực hiện nối tiếp."},{"ten":"B. THỰC HÀNH - ÔN TẬP BÀI HÁT (12 phút)","gv":"Mục tiêu: HS ôn hát và vận động theo bài Dàn nhạc trong vườn.\n- HS ôn lại bài hát 1–2 lần theo các hình thức: hát tập thể, hát nối tiếp, hát đối đáp nam nữ.\n- GV hướng dẫn hát kết hợp vận động theo nhịp (nhún chân sang phải – trái).\n- Chia lớp thành nhóm: nhóm hát – nhóm vận động; khuyến khích ý tưởng mới.","hs":"- HS ôn hát theo nhiều hình thức.\n- HS hát kết hợp vận động; trình bày tại chỗ/lên bảng."},{"ten":"C. KHÁM PHÁ - NGHE CÂU CHUYỆN (10 phút)","gv":"Mục tiêu: HS hiểu nội dung câu chuyện Ước mơ của bạn Đô và nhận biết nhạc cụ kèn đồng.\n- GV tạo các loại âm thanh (giấy, li, muỗng…) và đặt câu hỏi: Âm thanh phát ra từ đâu? Ở nhà/vào tiết chào cờ em thường nghe âm thanh gì?\n- GV giới thiệu nhạc cụ kèn đồng: âm thanh trầm hùng, vang xa; thường nghe ở bài Quốc ca, tiết chào cờ, doanh trại bộ đội.\n- GV kể chuyện Ước mơ của bạn Đô theo 4 bức tranh, gợi ý HS trả lời và kể lại; hỏi nhạc cụ nào được nhắc đến (kèn đồng).","hs":"- HS nghe, cảm nhận, trả lời câu hỏi về âm thanh.\n- HS xem tranh, lắng nghe câu chuyện, kể lại và trả lời: nhạc cụ kèn đồng."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở bản kể chuyện có nhạc minh hoạ cho “Ước mơ của bạn Đô”, dừng lại ở mỗi lần một nhân vật xuất hiện để HS nghe kĩ nhạc cụ nào đang thay lời nhân vật đó; nhờ nghe đi nghe lại đúng đoạn, HS nhận ra âm nhạc đang kể chuyện chứ không chỉ làm nền.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) HS làm bài tập tương tác có chấm ngay về “Ước mơ của bạn Đô”: nghe đoạn nhạc rồi chọn đúng nhân vật, sắp lại thứ tự diễn biến câu chuyện; sai chỗ nào HS nghe lại đúng đoạn nhạc đó rồi chọn lần nữa.\n⚠ (Miền 4: An toàn) Tư liệu về “Ước mơ của bạn Đô” phải lấy từ trang của nhà xuất bản, nhà hát, bảo tàng hoặc kênh chính thức của nghệ sĩ và tải sẵn về máy trước giờ lên lớp để không lẫn quảng cáo; khi kể lại cho người khác phải nói rõ mình đã xem ở đâu, không nhận tư liệu của người khác là của mình; mở âm lượng vừa đủ nghe.","hs":"- HS nêu được đặc điểm nổi bật của “Ước mơ của bạn Đô” nhờ quan sát tư liệu số và nghe bản thu.\n- HS làm bài tập tương tác, nhận ra âm sắc – nội dung đã học và tự sửa khi chọn sai."},{"ten":"E. CỦNG CỐ - DẶN DÒ (2 phút)","gv":"- GV hệ thống lại nội dung tiết học, nhận xét tiết học (khen ngợi, nhắc nhở).\n- GV dặn HS về nhà ôn lại bài, tập biểu diễn cho người thân nghe, chuẩn bị bài tiết sau và làm bài trong vở bài tập (nếu có).","hs":"- HS lắng nghe, ghi nhớ.\n- HS hát/đọc nhạc lại một lần để kết thúc tiết học vui vẻ."}],"hotro":"","hoanhap":"","status":"checked","source":"KHBD Âm nhạc 2 KNTT — Bút Xanh (biên soạn tích hợp NLS + AI)"},
{"lop":2,"mon":"Âm nhạc","tuan":3,"tiet":3,"bai":"Chủ đề 1: Sắc màu âm thanh — Đọc nhạc: Bài số 1","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Nhớ tên các nốt Đô – Rê – Mi – Pha – Son – La; đọc được cao độ, trường độ bài đọc nhạc số 1 kết hợp kí hiệu bàn tay và nhạc đệm.\n- Biết đọc nhạc và vận dụng gõ đệm theo nhịp; cảm nhận yếu tố mạnh – nhẹ.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động tập luyện, mạnh dạn thể hiện bài hát/bài đọc nhạc; tự điều chỉnh khi hát/gõ chưa đúng.\n- Giao tiếp và hợp tác: Biết hát, gõ đệm, vận động theo nhóm; lắng nghe và phối hợp nhịp nhàng cùng bạn.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm hoặc ý tưởng biểu diễn đơn giản.\n3. Phẩm chất\n- Chăm chỉ: Tích cực tham gia các hoạt động ca hát, đọc nhạc, trò chơi âm nhạc.\n- Yêu thích môn Âm nhạc; cảm nhận được vẻ đẹp của âm thanh.\n4. Tích hợp\n- Năng lực số 1.1 CB1 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS đọc đúng cao độ “Bài số 1” nhờ nghe mẫu từ đàn phím.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ cơ bản (thanh phách, song loan, trống con, ma-ra-cát).\n- HS: SGK Âm nhạc 2 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ cơ bản (thanh phách, song loan) nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"- Trò chơi \"Ai nhớ tài hơn\": GV mời một số HS đóng vai các nốt Đô, Rê, Mi, Pha, Son, La theo chiều cao dần; 1 HS làm MC giới thiệu, cả lớp đọc tên nốt theo kí hiệu bàn tay.","hs":"- HS lắng nghe, tham gia trò chơi vui vẻ."},{"ten":"B. KHÁM PHÁ - ĐỌC NHẠC (15 phút)","gv":"Mục tiêu: HS đọc đúng cao độ, tên nốt bài đọc nhạc số 1.\n- GV cho HS quan sát tranh 5 bạn Đô – Rê – Mi – Son – La trên phím đàn; hỏi bạn nào thấp/cao nhất; đọc tên từ thấp đến cao.\n- GV bấm đàn, đọc cao độ các nốt; HS đọc theo.\n- GV đọc mẫu bài đọc nhạc số 1, đọc tên nốt từng câu, HS đọc theo.\n- Tập đọc nhạc theo kí hiệu bàn tay; đọc với nhiều hình thức: cá nhân/nhóm/tổ/cả lớp.","hs":"- HS quan sát, trả lời, ghi nhớ cao độ.\n- HS đọc theo cao độ đàn, đọc tên nốt, thể hiện kí hiệu bàn tay."},{"ten":"C. THỰC HÀNH - LUYỆN TẬP (10 phút)","gv":"Mục tiêu: HS đọc nhạc với nhạc đệm và vỗ tay mạnh – nhẹ theo nhịp.\n- GV mở file nhạc đệm, đọc mẫu, hướng dẫn HS đọc theo với nhiều hình thức.\n- GV hướng dẫn nghe và vỗ tay mạnh (bông hoa đỏ) – nhẹ (bông hoa vàng) theo hình, cảm thụ nhịp nhàng của nhịp 3.","hs":"- HS đọc nhạc theo nhạc đệm, kết hợp vận động tự do.\n- HS vỗ tay mạnh – nhẹ theo nhịp."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV dùng đàn phím điện tử hoặc phần mềm đàn phím trên máy tính để lấy cao độ chuẩn cho “Bài số 1”: bấm từng nốt cho HS nghe rõ, bấm chậm cả câu, rồi bấm lại đúng nốt mà HS còn đọc chênh — cao độ lấy từ đàn chuẩn hơn lấy từ giọng người vì không bị lệch theo hơi thở.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV mở trò chơi nghe nốt trên máy: máy phát một nốt, HS giơ kí hiệu bàn tay tương ứng, GV bấm lại nốt đó để cả lớp cùng kiểm tra ngay đúng hay sai rồi đọc lại — HS biết mình sai ở nốt nào ngay tại chỗ chứ không chờ hết giờ.\n⚠ (Miền 4: An toàn) GV thao tác đàn và máy tính, HS chỉ nghe và đọc theo, không tự bấm vào thiết bị của GV; mở âm lượng vừa đủ nghe để không hại tai; chỉ dùng phần mềm GV đã cài sẵn, không mở phần mềm hay trang khác trong giờ học.","hs":"- HS đọc đúng cao độ “Bài số 1” nhờ nghe mẫu từ đàn phím.\n- HS nhận ra ngay nốt mình đọc còn chênh và đọc lại cho đúng."},{"ten":"E. CỦNG CỐ - DẶN DÒ (2 phút)","gv":"- GV hệ thống lại nội dung tiết học, nhận xét tiết học (khen ngợi, nhắc nhở).\n- GV dặn HS về nhà ôn lại bài, tập biểu diễn cho người thân nghe, chuẩn bị bài tiết sau và làm bài trong vở bài tập (nếu có).","hs":"- HS lắng nghe, ghi nhớ.\n- HS hát/đọc nhạc lại một lần để kết thúc tiết học vui vẻ."}],"hotro":"","hoanhap":"","status":"checked","source":"KHBD Âm nhạc 2 KNTT — Bút Xanh (biên soạn tích hợp NLS + AI)"},
{"lop":2,"mon":"Âm nhạc","tuan":4,"tiet":4,"bai":"Chủ đề 1: Sắc màu âm thanh — Ôn tập: Hát và Đọc nhạc; Vận dụng – Sáng tạo","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Biểu diễn bài hát Dàn nhạc trong vườn nhịp nhàng theo nhịp 3/4 kết hợp ý tưởng sáng tạo.\n- Thể hiện bài đọc nhạc số 1 kết hợp nhạc cụ đệm và vận động; đọc đồng dao và gõ theo hình tiết tấu.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động tập luyện, mạnh dạn thể hiện bài hát/bài đọc nhạc; tự điều chỉnh khi hát/gõ chưa đúng.\n- Giao tiếp và hợp tác: Biết hát, gõ đệm, vận động theo nhóm; lắng nghe và phối hợp nhịp nhàng cùng bạn.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm hoặc ý tưởng biểu diễn đơn giản.\n3. Phẩm chất\n- Chăm chỉ: Tích cực tham gia các hoạt động ca hát, đọc nhạc, trò chơi âm nhạc.\n- Yêu thích môn Âm nhạc; cảm nhận được vẻ đẹp của âm thanh.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ cơ bản (thanh phách, song loan, trống con, ma-ra-cát).\n- HS: SGK Âm nhạc 2 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ cơ bản (thanh phách, song loan) nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"- HS hát lại bài Dàn nhạc trong vườn để khởi động giọng.","hs":"- HS hát lại bài hát vui vẻ."},{"ten":"B. THỰC HÀNH - ÔN TẬP (13 phút)","gv":"Mục tiêu: HS ôn hát và ôn đọc nhạc theo nhiều hình thức.\n- Ôn bài hát: HS hát với nhạc đệm và vận động; trình bày theo các hình thức nhóm hát, nhóm gõ, nhóm vận động, nhóm phụ hoạ.\n- Ôn đọc nhạc số 1 với nhạc đệm ở các hình thức: nhóm đọc nhạc, nhóm gõ, nhóm vận động.\n- GV trao đổi, góp ý để HS hoàn thiện hơn.","hs":"- HS ôn hát, ôn đọc nhạc; tự nhận xét cho mình và nhóm bạn."},{"ten":"C. VẬN DỤNG - SÁNG TẠO (12 phút)","gv":"Mục tiêu: HS đọc đồng dao và gõ theo hình tiết tấu.\n- GV giới thiệu đồng dao là thể ca dân gian truyền miệng của trẻ em Việt Nam.\n- GV đọc mẫu tiết tấu, HS đọc theo; đọc bài đồng dao theo tiết tấu.\n- HS dùng thanh phách (hoặc vỗ tay) vừa đọc đồng dao vừa gõ theo hình tiết tấu; chia tổ luân phiên; mời cá nhân thực hiện.","hs":"- HS lắng nghe, đọc đồng dao theo tiết tấu.\n- HS gõ thanh phách/vỗ tay theo tiết tấu; các tổ, cá nhân thực hiện."},{"ten":"E. CỦNG CỐ - DẶN DÒ (2 phút)","gv":"- GV hệ thống lại nội dung tiết học, nhận xét tiết học (khen ngợi, nhắc nhở).\n- GV dặn HS về nhà ôn lại bài, tập biểu diễn cho người thân nghe, chuẩn bị bài tiết sau và làm bài trong vở bài tập (nếu có).","hs":"- HS lắng nghe, ghi nhớ.\n- HS hát/đọc nhạc lại một lần để kết thúc tiết học vui vẻ."}],"hotro":"","hoanhap":"","status":"checked","source":"KHBD Âm nhạc 2 KNTT — Bút Xanh (biên soạn tích hợp NLS + AI)"},
{"lop":2,"mon":"Âm nhạc","tuan":5,"tiet":5,"bai":"Chủ đề 2: Em yêu làn điệu dân ca — Học hát: Con chim chích choè (Dân ca Nam Bộ, lời mới: Việt Anh)","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Hát đúng giai điệu, lời ca bài Con chim chích choè; biết bài hát theo điệu Bắc kim thang – dân ca Nam Bộ, lời mới của Việt Anh.\n- Hình thành kĩ năng hát (lấy hơi, rõ lời); biết hát kết hợp gõ đệm theo phách, theo tiết tấu.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động tập luyện, mạnh dạn thể hiện bài hát/bài đọc nhạc; tự điều chỉnh khi hát/gõ chưa đúng.\n- Giao tiếp và hợp tác: Biết hát, gõ đệm, vận động theo nhóm; lắng nghe và phối hợp nhịp nhàng cùng bạn.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm hoặc ý tưởng biểu diễn đơn giản.\n3. Phẩm chất\n- Nhân ái, yêu quê hương: Biết yêu các bài hát dân ca.\n- Chăm chỉ: Tích cực tham gia các hoạt động ca hát, đọc nhạc, trò chơi âm nhạc.\n- Yêu thích môn Âm nhạc; cảm nhận được vẻ đẹp của âm thanh.\n4. Tích hợp\n- Năng lực số 1.1 CB1 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS nghe bản thu mẫu và hát đúng lời, đúng cao độ bài “Con chim chích choè”.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ cơ bản (thanh phách, song loan, trống con, ma-ra-cát).\n- HS: SGK Âm nhạc 2 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ cơ bản (thanh phách, song loan) nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"- HS hát lại bài Dàn nhạc trong vườn để khởi động giọng.\n- Trò chơi \"Gõ đệm theo hình tiết tấu\": GV gõ cốc xuống bàn theo tiết tấu, HS quan sát và làm theo; luân phiên đối đáp giữa các nhóm bằng nhạc cụ gõ tự chế.","hs":"- HS hát khởi động; quan sát, gõ đệm luân phiên các nhóm."},{"ten":"B. KHÁM PHÁ - HỌC HÁT (15 phút)","gv":"Mục tiêu: HS hát đúng bài Con chim chích choè.\n- GV cho xem hình ảnh chim chích choè, bản đồ vùng Nam Bộ và giới thiệu: bài viết theo điệu Bắc kim thang – dân ca Nam Bộ, tính chất vui vẻ, hài hước.\n- GV hát mẫu; hướng dẫn đọc lời ca theo tiết tấu (chia 6 câu).\n- Dạy hát nối tiếp từng câu; luyện các tiếng hát luyến; cho HS hát nhiều lần cho thuộc, đúng giai điệu.","hs":"- HS quan sát, lắng nghe giới thiệu và hát mẫu.\n- HS đọc lời ca, học hát từng câu, luyện hát cho thuộc."},{"ten":"C. THỰC HÀNH - LUYỆN TẬP (10 phút)","gv":"Mục tiêu: HS hát kết hợp gõ đệm theo phách và vận động.\n- GV hát và gõ đệm mẫu theo phách (bông hoa đỏ – vàng).\n- Hướng dẫn HS hát + gõ đệm theo phách; chia 4 nhóm: 2 nhóm hát, 1 nhóm gõ đệm, 1 nhóm vận động (luân phiên).\n- GV chọn 1 nhóm lên biểu diễn; giáo dục ý thức tự bảo vệ (đội mũ khi trời nắng).","hs":"- HS hát + gõ đệm theo phách; các nhóm thực hiện luân phiên.\n- 1 nhóm biểu diễn; HS trả lời, nghe giáo dục."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở bản thu mẫu bài “Con chim chích choè” lấy từ học liệu điện tử của bộ sách hoặc kênh chính thức của nhà xuất bản, phóng màn hình để cả lớp nhìn thấy tên bài hát, chỉ cho HS dòng ghi tác giả “Dân ca Nam Bộ, lời mới: Việt Anh”; GV mở từng câu, tạm dừng cho HS nghe kĩ rồi hát theo, câu nào HS hát chênh cao độ thì GV mở lại đúng câu đó.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV dùng điện thoại thu âm phần hát bài “Con chim chích choè” của cả lớp rồi mở lại ngay cho HS nghe; HS chỉ ra chỗ mình hát to quá, nhỏ quá hoặc sai lời — nghe lại giọng của chính mình là điều hát chay không có được. GV thao tác thiết bị, HS nghe và nhận xét.\n⚠ (Miền 4: An toàn) Bản thu bài “Con chim chích choè” chỉ lấy từ học liệu của bộ sách hoặc kênh chính thức, không tải nhạc từ trang lạ vì có thể sai lời, sai nhạc và kèm quảng cáo không phù hợp; giới thiệu bài hát phải nói rõ tên tác giả; mở loa vừa đủ nghe, không để loa sát tai HS.","hs":"- HS nghe bản thu mẫu và hát đúng lời, đúng cao độ bài “Con chim chích choè”.\n- HS nói được tên bài hát cùng tên tác giả; nghe lại bản thu của lớp và chỉ ra một chỗ cần sửa."},{"ten":"E. CỦNG CỐ - DẶN DÒ (2 phút)","gv":"- GV hệ thống lại nội dung tiết học, nhận xét tiết học (khen ngợi, nhắc nhở).\n- GV dặn HS về nhà ôn lại bài, tập biểu diễn cho người thân nghe, chuẩn bị bài tiết sau và làm bài trong vở bài tập (nếu có).","hs":"- HS lắng nghe, ghi nhớ.\n- HS hát/đọc nhạc lại một lần để kết thúc tiết học vui vẻ."}],"hotro":"","hoanhap":"","status":"checked","source":"KHBD Âm nhạc 2 KNTT — Bút Xanh (biên soạn tích hợp NLS + AI)"},
{"lop":2,"mon":"Âm nhạc","tuan":6,"tiet":6,"bai":"Chủ đề 2: Em yêu làn điệu dân ca — Ôn tập bài hát: Con chim chích choè; Nhạc cụ: Giới thiệu nhạc cụ Song loan","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Hát được giai điệu, đúng lời ca bài Con chim chích choè; hát kết hợp gõ đệm và vận động.\n- Nhận biết nhạc cụ gõ song loan; biết cách cầm, cách chơi và dùng song loan gõ đệm theo tiết tấu, theo bài hát.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động tập luyện, mạnh dạn thể hiện bài hát/bài đọc nhạc; tự điều chỉnh khi hát/gõ chưa đúng.\n- Giao tiếp và hợp tác: Biết hát, gõ đệm, vận động theo nhóm; lắng nghe và phối hợp nhịp nhàng cùng bạn.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm hoặc ý tưởng biểu diễn đơn giản.\n3. Phẩm chất\n- Nhân ái, yêu quê hương: Yêu các bài hát dân ca, yêu nhạc cụ dân tộc.\n- Chăm chỉ: Tích cực tham gia các hoạt động ca hát, đọc nhạc, trò chơi âm nhạc.\n- Yêu thích môn Âm nhạc; cảm nhận được vẻ đẹp của âm thanh.\n4. Tích hợp\n- Năng lực số 1.1 CB1 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS cầm và gõ được nhạc cụ Song loan đúng cách sau khi xem phim cận cảnh.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ cơ bản (thanh phách, song loan, trống con, ma-ra-cát).\n- HS: SGK Âm nhạc 2 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ cơ bản (thanh phách, song loan) nếu có.\n- Nhạc cụ song loan (thật hoặc hình ảnh/video).","hoatdong":[{"ten":"A. KHỞI ĐỘNG (4 phút)","gv":"- HS hát lại bài Con chim chích choè để khởi động giọng.\n- Trò chơi gõ đệm theo hình tiết tấu bằng các nhạc cụ gõ đã học (thanh phách, trống nhỏ, ma-ra-cát).","hs":"- HS hát; chuẩn bị nhạc cụ, gõ đệm theo tiết tấu."},{"ten":"B. THỰC HÀNH - ÔN TẬP BÀI HÁT (10 phút)","gv":"Mục tiêu: HS ôn hát Con chim chích choè theo nhiều hình thức.\n- GV hướng dẫn ôn với các hình thức đơn ca, song ca, hát đối đáp.\n- Hát kết hợp gõ đệm theo phách; hát kết hợp vỗ tay theo tiết tấu lời ca.\n- Biểu diễn bài hát; HS quan sát, nhận xét lẫn nhau.","hs":"- HS ôn hát; hát kết hợp gõ đệm, vỗ tay; biểu diễn và nhận xét."},{"ten":"C. KHÁM PHÁ - NHẠC CỤ SONG LOAN (14 phút)","gv":"Mục tiêu: HS nhận biết và sử dụng nhạc cụ song loan.\n- GV giới thiệu, hướng dẫn HS cách cầm, cách chơi và âm thanh của song loan (đúng tư thế).\n- GV gõ âm thanh cho HS nghe, HD gõ tự do cho quen tay.\n- HS luyện gõ theo hình tiết tấu; dùng song loan gõ đệm theo phách vào bài Con chim chích choè.\n- Luyện tập/trình bày (gõ đệm, hát) theo cá nhân, cặp, nhóm.","hs":"- HS quan sát, lắng nghe, tập cầm và gõ song loan.\n- HS luyện tiết tấu, gõ đệm theo phách vào bài hát; trình bày theo nhóm."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu đoạn phim quay cận cảnh nhạc cụ Song loan: nhìn rõ hình dáng, chất liệu, cách cầm và cách gõ sao cho ra đúng tiếng; GV tua chậm đúng động tác khó, cho xem lại hai ba lần rồi mới phát nhạc cụ thật để HS làm theo.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV thu âm tiếng gõ Song loan của từng tổ rồi mở lại cho cả lớp nghe; HS nghe ra tổ nào gõ đều, tổ nào còn lúc nhanh lúc chậm — nghe lại bản thu giúp HS nhận ra điều mà lúc đang gõ không nhận ra được.\n⚠ (Miền 4: An toàn) Cầm Song loan đúng cách, gõ vừa lực, không đập mạnh xuống bàn và không chĩa vào người bạn; GV thao tác máy chiếu và điện thoại, HS không tự cầm thiết bị; bản thu tiếng gõ của lớp chỉ mở trong giờ học, không gửi ra ngoài lớp.","hs":"- HS cầm và gõ được nhạc cụ Song loan đúng cách sau khi xem phim cận cảnh.\n- HS nghe lại bản thu tiếng gõ của tổ và chỉ ra chỗ gõ chưa đều."},{"ten":"E. CỦNG CỐ - DẶN DÒ (2 phút)","gv":"- GV hệ thống lại nội dung tiết học, nhận xét tiết học (khen ngợi, nhắc nhở).\n- GV dặn HS về nhà ôn lại bài, tập biểu diễn cho người thân nghe, chuẩn bị bài tiết sau và làm bài trong vở bài tập (nếu có).","hs":"- HS lắng nghe, ghi nhớ.\n- HS hát/đọc nhạc lại một lần để kết thúc tiết học vui vẻ."}],"hotro":"","hoanhap":"","status":"checked","source":"KHBD Âm nhạc 2 KNTT — Bút Xanh (biên soạn tích hợp NLS + AI)"},
{"lop":2,"mon":"Âm nhạc","tuan":7,"tiet":7,"bai":"Chủ đề 2: Em yêu làn điệu dân ca — Thường thức âm nhạc: Đàn bầu Việt Nam; Vận dụng – Sáng tạo","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Nhận biết đàn bầu là nhạc cụ dân tộc của Việt Nam; biết hình dáng, âm sắc của đàn bầu.\n- Chăm chú nghe và biểu hiện cảm xúc khi nghe tiếng đàn bầu qua bài Trống cơm; dùng song loan gõ đệm theo nhịp điệu bài Múa sạp.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động tập luyện, mạnh dạn thể hiện bài hát/bài đọc nhạc; tự điều chỉnh khi hát/gõ chưa đúng.\n- Giao tiếp và hợp tác: Biết hát, gõ đệm, vận động theo nhóm; lắng nghe và phối hợp nhịp nhàng cùng bạn.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm hoặc ý tưởng biểu diễn đơn giản.\n3. Phẩm chất\n- Yêu quê hương, nhân ái: Yêu nhạc cụ dân tộc, yêu âm nhạc.\n- Chăm chỉ: Tích cực tham gia các hoạt động ca hát, đọc nhạc, trò chơi âm nhạc.\n- Yêu thích môn Âm nhạc; cảm nhận được vẻ đẹp của âm thanh.\n4. Tích hợp\n- Năng lực số 1.1 CB1 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS nêu được đặc điểm nổi bật của “Đàn bầu Việt Nam” nhờ quan sát tư liệu số và nghe bản thu.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ cơ bản (thanh phách, song loan, trống con, ma-ra-cát).\n- HS: SGK Âm nhạc 2 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ cơ bản (thanh phách, song loan) nếu có.\n- Nhạc cụ đàn bầu (hoặc hình ảnh/video); file bài Trống cơm, Múa sạp.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (3 phút)","gv":"- HS ổn định, hát lại bài Con chim chích choè kết hợp gõ đệm theo phách.","hs":"- HS hát và gõ đệm khởi động."},{"ten":"B. KHÁM PHÁ - THƯỜNG THỨC ÂM NHẠC (17 phút)","gv":"Mục tiêu: HS nhận biết đàn bầu và cảm thụ tiếng đàn qua bài Trống cơm.\n- GV cho HS xem hình ảnh/video giới thiệu đàn bầu và một đoạn độc tấu; giới thiệu: đàn bầu là nhạc cụ dân tộc độc đáo của Việt Nam, chỉ có một dây, âm thanh ngân nga sâu lắng.\n- Trò chơi \"nghe giai điệu đoán tên nhạc cụ\": phát lần lượt độc tấu vài nhạc cụ (violon, nhị, bầu), HS đoán đoạn nào là tiếng đàn bầu.\n- Giới thiệu bài Trống cơm (dân ca quan họ Bắc Ninh); cho HS nghe và vận động nhịp nhàng theo bài.","hs":"- HS quan sát, lắng nghe tiếng đàn bầu, tham gia trò chơi đoán nhạc cụ.\n- HS nghe bài Trống cơm, vận động nhịp nhàng, nêu cảm nhận."},{"ten":"C. VẬN DỤNG - SÁNG TẠO (10 phút)","gv":"Mục tiêu: HS gõ đệm theo nhịp điệu bài Múa sạp.\n- GV giới thiệu Múa sạp là trò chơi kết hợp múa dân gian của dân tộc Mường, Thái.\n- GV đọc và gõ mẫu thanh phách theo nhịp bài Múa sạp; HS đọc và gõ theo.\n- Bật nhạc nền cho HS vừa hát/vừa gõ; chia lớp 2 nửa: nửa hát, nửa gõ và ngược lại.","hs":"- HS lắng nghe, đọc và gõ thanh phách theo nhịp bài Múa sạp.\n- HS chia nửa hát – gõ luân phiên."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu đoạn phim quay cận cảnh cho nội dung “Đàn bầu Việt Nam”: nhìn rõ hình dáng, chất liệu, số dây hoặc số lỗ, bàn tay nghệ sĩ đặt ở đâu và làm động tác gì để ra tiếng; GV tua chậm và dừng đúng chỗ đó — chi tiết này tranh in trong sách và một lần nghe trên lớp không cho thấy được.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) HS làm bài tập nghe tương tác có chấm ngay: GV mở lần lượt vài đoạn nhạc ngắn, HS chọn đoạn nào có âm sắc của nhạc cụ vừa học trong “Đàn bầu Việt Nam”; chọn sai thì nghe lại đoạn đó và chọn lần nữa cho tới khi nhận ra đúng.\n⚠ (Miền 4: An toàn) Tư liệu về “Đàn bầu Việt Nam” phải lấy từ trang của nhà xuất bản, nhà hát, bảo tàng hoặc kênh chính thức của nghệ sĩ và tải sẵn về máy trước giờ lên lớp để không lẫn quảng cáo; khi kể lại cho người khác phải nói rõ mình đã xem ở đâu, không nhận tư liệu của người khác là của mình; mở âm lượng vừa đủ nghe.","hs":"- HS nêu được đặc điểm nổi bật của “Đàn bầu Việt Nam” nhờ quan sát tư liệu số và nghe bản thu.\n- HS làm bài tập tương tác, nhận ra âm sắc – nội dung đã học và tự sửa khi chọn sai."},{"ten":"E. CỦNG CỐ - DẶN DÒ (2 phút)","gv":"- GV hệ thống lại nội dung tiết học, nhận xét tiết học (khen ngợi, nhắc nhở).\n- GV dặn HS về nhà ôn lại bài, tập biểu diễn cho người thân nghe, chuẩn bị bài tiết sau và làm bài trong vở bài tập (nếu có).","hs":"- HS lắng nghe, ghi nhớ.\n- HS hát/đọc nhạc lại một lần để kết thúc tiết học vui vẻ."}],"hotro":"","hoanhap":"","status":"checked","source":"KHBD Âm nhạc 2 KNTT — Bút Xanh (biên soạn tích hợp NLS + AI)"},
{"lop":2,"mon":"Âm nhạc","tuan":8,"tiet":8,"bai":"Chủ đề 2: Em yêu làn điệu dân ca — Ôn tập chủ đề 2; Vận dụng – Sáng tạo","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Biểu diễn thuần thục bài Con chim chích choè kết hợp gõ đệm, vận động phụ hoạ; sử dụng song loan gõ đệm.\n- Củng cố hiểu biết về nhạc cụ dân tộc (song loan, đàn bầu); tham gia trò chơi âm nhạc sáng tạo.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động tập luyện, mạnh dạn thể hiện bài hát/bài đọc nhạc; tự điều chỉnh khi hát/gõ chưa đúng.\n- Giao tiếp và hợp tác: Biết hát, gõ đệm, vận động theo nhóm; lắng nghe và phối hợp nhịp nhàng cùng bạn.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm hoặc ý tưởng biểu diễn đơn giản.\n3. Phẩm chất\n- Nhân ái, yêu quê hương.\n- Chăm chỉ: Tích cực tham gia các hoạt động ca hát, đọc nhạc, trò chơi âm nhạc.\n- Yêu thích môn Âm nhạc; cảm nhận được vẻ đẹp của âm thanh.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ cơ bản (thanh phách, song loan, trống con, ma-ra-cát).\n- HS: SGK Âm nhạc 2 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ cơ bản (thanh phách, song loan) nếu có.\n- Nhạc cụ song loan.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (4 phút)","gv":"- Trò chơi \"nghe giai điệu đoán tên bài hát\" các bài đã học trong chủ đề.","hs":"- HS lắng nghe giai điệu và đoán tên bài hát."},{"ten":"B. THỰC HÀNH - ÔN TẬP (14 phút)","gv":"Mục tiêu: HS biểu diễn bài Con chim chích choè kết hợp gõ đệm, vận động.\n- HS ôn hát với nhiều hình thức; kết hợp vận động phụ hoạ và gõ đệm bằng song loan, thanh phách.\n- Chia nhóm biểu diễn: nhóm hát, nhóm gõ đệm, nhóm vận động; luân phiên.\n- GV nhận xét, sửa sai, tuyên dương.","hs":"- HS ôn hát, gõ đệm, vận động; các nhóm biểu diễn và nhận xét lẫn nhau."},{"ten":"C. VẬN DỤNG - SÁNG TẠO (10 phút)","gv":"Mục tiêu: HS sáng tạo động tác và gõ đệm theo tiết tấu.\n- GV cho HS tự nghĩ và biểu diễn vài động tác phụ hoạ đơn giản cho bài hát.\n- Tổ chức thi biểu diễn nhóm; khen ngợi ý tưởng sáng tạo.","hs":"- HS sáng tạo động tác, luyện tập trong nhóm và lên biểu diễn."},{"ten":"E. CỦNG CỐ - DẶN DÒ (2 phút)","gv":"- GV hệ thống lại nội dung tiết học, nhận xét tiết học (khen ngợi, nhắc nhở).\n- GV dặn HS về nhà ôn lại bài, tập biểu diễn cho người thân nghe, chuẩn bị bài tiết sau và làm bài trong vở bài tập (nếu có).","hs":"- HS lắng nghe, ghi nhớ.\n- HS hát/đọc nhạc lại một lần để kết thúc tiết học vui vẻ."}],"hotro":"","hoanhap":"","status":"checked","source":"KHBD Âm nhạc 2 KNTT — Bút Xanh (biên soạn tích hợp NLS + AI)"},
{"lop":2,"mon":"Âm nhạc","tuan":9,"tiet":9,"bai":"Chủ đề 3: Mái trường thân yêu — Học hát: Học sinh lớp Hai chăm ngoan (Nhạc và lời: Hoàng Long)","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Nêu được tên bài hát và tác giả; hát đúng giai điệu, lời ca bài Học sinh lớp Hai chăm ngoan.\n- Cảm nhận và thể hiện bài hát với tính chất vui tươi, trong sáng, tốc độ hơi nhanh ở nhịp 2/4; biết hát gõ đệm theo phách.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động tập luyện, mạnh dạn thể hiện bài hát/bài đọc nhạc; tự điều chỉnh khi hát/gõ chưa đúng.\n- Giao tiếp và hợp tác: Biết hát, gõ đệm, vận động theo nhóm; lắng nghe và phối hợp nhịp nhàng cùng bạn.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm hoặc ý tưởng biểu diễn đơn giản.\n3. Phẩm chất\n- Chăm chỉ, trách nhiệm: Biết chăm ngoan, nghe lời ông bà, cha mẹ, thầy cô.\n- Chăm chỉ: Tích cực tham gia các hoạt động ca hát, đọc nhạc, trò chơi âm nhạc.\n- Yêu thích môn Âm nhạc; cảm nhận được vẻ đẹp của âm thanh.\n4. Tích hợp\n- Năng lực số 1.1 CB1 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS nghe bản thu mẫu và hát đúng lời, đúng cao độ bài “Học sinh lớp Hai chăm ngoan”.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ cơ bản (thanh phách, song loan, trống con, ma-ra-cát).\n- HS: SGK Âm nhạc 2 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ cơ bản (thanh phách, song loan) nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (4 phút)","gv":"- GV cho HS hát lại một bài đã học; giới thiệu chủ đề Mái trường em yêu.\n- GV giới thiệu vài nét về nhạc sĩ Hoàng Long.","hs":"- HS hát khởi động, lắng nghe giới thiệu."},{"ten":"B. KHÁM PHÁ - HỌC HÁT (16 phút)","gv":"Mục tiêu: HS hát đúng bài Học sinh lớp Hai chăm ngoan.\n- GV hát mẫu (hoặc mở file), hỏi cảm nhận về tính chất bài hát (vui tươi, trong sáng).\n- Hướng dẫn đọc lời ca theo tiết tấu; chia câu và dạy hát nối tiếp từng câu.\n- Cho HS luyện hát cho thuộc, đúng giai điệu, tiết tấu; hát với tốc độ hơi nhanh, chú ý lấy hơi.","hs":"- HS nghe hát mẫu, nêu cảm nhận.\n- HS đọc lời ca, học hát từng câu, luyện hát cho thuộc."},{"ten":"C. THỰC HÀNH - LUYỆN TẬP (11 phút)","gv":"Mục tiêu: HS hát kết hợp gõ đệm theo phách.\n- GV hát và gõ đệm mẫu theo phách.\n- HS hát kết hợp gõ đệm theo phách với các hình thức tập thể, tổ, cá nhân.\n- GV nhận xét, sửa sai, giáo dục HS chăm ngoan.","hs":"- HS hát + gõ đệm theo phách; các tổ, cá nhân thực hiện."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở bản thu mẫu bài “Học sinh lớp Hai chăm ngoan” lấy từ học liệu điện tử của bộ sách hoặc kênh chính thức của nhà xuất bản, phóng màn hình để cả lớp nhìn thấy tên bài hát, chỉ cho HS dòng ghi tác giả “Nhạc và lời: Hoàng Long”; GV mở từng câu, tạm dừng cho HS nghe kĩ rồi hát theo, câu nào HS hát chênh cao độ thì GV mở lại đúng câu đó.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV dùng điện thoại thu âm phần hát bài “Học sinh lớp Hai chăm ngoan” của cả lớp rồi mở lại ngay cho HS nghe; HS chỉ ra chỗ mình hát to quá, nhỏ quá hoặc sai lời — nghe lại giọng của chính mình là điều hát chay không có được. GV thao tác thiết bị, HS nghe và nhận xét.\n⚠ (Miền 4: An toàn) Bản thu bài “Học sinh lớp Hai chăm ngoan” chỉ lấy từ học liệu của bộ sách hoặc kênh chính thức, không tải nhạc từ trang lạ vì có thể sai lời, sai nhạc và kèm quảng cáo không phù hợp; giới thiệu bài hát phải nói rõ tên tác giả; mở loa vừa đủ nghe, không để loa sát tai HS.","hs":"- HS nghe bản thu mẫu và hát đúng lời, đúng cao độ bài “Học sinh lớp Hai chăm ngoan”.\n- HS nói được tên bài hát cùng tên tác giả; nghe lại bản thu của lớp và chỉ ra một chỗ cần sửa."},{"ten":"E. CỦNG CỐ - DẶN DÒ (2 phút)","gv":"- GV hệ thống lại nội dung tiết học, nhận xét tiết học (khen ngợi, nhắc nhở).\n- GV dặn HS về nhà ôn lại bài, tập biểu diễn cho người thân nghe, chuẩn bị bài tiết sau và làm bài trong vở bài tập (nếu có).","hs":"- HS lắng nghe, ghi nhớ.\n- HS hát/đọc nhạc lại một lần để kết thúc tiết học vui vẻ."}],"hotro":"","hoanhap":"","status":"checked","source":"KHBD Âm nhạc 2 KNTT — Bút Xanh (biên soạn tích hợp NLS + AI)"},
{"lop":2,"mon":"Âm nhạc","tuan":10,"tiet":10,"bai":"Chủ đề 3: Mái trường thân yêu — Ôn tập bài hát: Học sinh lớp Hai chăm ngoan; Đọc nhạc theo kí hiệu bàn tay","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Hát thuộc, đúng giai điệu bài Học sinh lớp Hai chăm ngoan; hát kết hợp vận động.\n- Đọc được các nốt Đô – Rê – Mi – Pha – Son – La kết hợp kí hiệu bàn tay.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động tập luyện, mạnh dạn thể hiện bài hát/bài đọc nhạc; tự điều chỉnh khi hát/gõ chưa đúng.\n- Giao tiếp và hợp tác: Biết hát, gõ đệm, vận động theo nhóm; lắng nghe và phối hợp nhịp nhàng cùng bạn.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm hoặc ý tưởng biểu diễn đơn giản.\n3. Phẩm chất\n- Chăm chỉ, trách nhiệm.\n- Chăm chỉ: Tích cực tham gia các hoạt động ca hát, đọc nhạc, trò chơi âm nhạc.\n- Yêu thích môn Âm nhạc; cảm nhận được vẻ đẹp của âm thanh.\n4. Tích hợp\n- Năng lực số 1.1 CB1 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS đọc đúng cao độ “đọc nhạc theo kí hiệu bàn tay” nhờ nghe mẫu từ đàn phím.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ cơ bản (thanh phách, song loan, trống con, ma-ra-cát).\n- HS: SGK Âm nhạc 2 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ cơ bản (thanh phách, song loan) nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (4 phút)","gv":"- Trò chơi \"Nghe giai điệu đoán tên bài hát\".","hs":"- HS lắng nghe và đoán tên bài hát."},{"ten":"B. THỰC HÀNH - ÔN TẬP BÀI HÁT (13 phút)","gv":"Mục tiêu: HS ôn hát và vận động theo bài.\n- HS ôn bài Học sinh lớp Hai chăm ngoan với nhạc đệm, hát kết hợp vận động cơ thể.\n- Trình bày theo hình thức nhóm hát, nhóm gõ, nhóm vận động.\n- GV nhận xét, hoàn thiện.","hs":"- HS ôn hát, vận động; trình bày theo nhóm."},{"ten":"C. KHÁM PHÁ - ĐỌC NHẠC KÍ HIỆU BÀN TAY (11 phút)","gv":"Mục tiêu: HS đọc các nốt kết hợp kí hiệu bàn tay.\n- GV ôn kí hiệu bàn tay các nốt Đô – Rê – Mi – Pha – Son – La.\n- GV đọc mẫu theo kí hiệu bàn tay, HS đọc theo.\n- Luyện đọc theo nhiều hình thức: cá nhân/nhóm/tổ/cả lớp.","hs":"- HS quan sát, thể hiện kí hiệu bàn tay và đọc tên nốt."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV dùng đàn phím điện tử hoặc phần mềm đàn phím trên máy tính để lấy cao độ chuẩn cho “đọc nhạc theo kí hiệu bàn tay”: bấm từng nốt cho HS nghe rõ, bấm chậm cả câu, rồi bấm lại đúng nốt mà HS còn đọc chênh — cao độ lấy từ đàn chuẩn hơn lấy từ giọng người vì không bị lệch theo hơi thở.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV mở trò chơi nghe nốt trên máy: máy phát một nốt, HS giơ kí hiệu bàn tay tương ứng, GV bấm lại nốt đó để cả lớp cùng kiểm tra ngay đúng hay sai rồi đọc lại — HS biết mình sai ở nốt nào ngay tại chỗ chứ không chờ hết giờ.\n⚠ (Miền 4: An toàn) GV thao tác đàn và máy tính, HS chỉ nghe và đọc theo, không tự bấm vào thiết bị của GV; mở âm lượng vừa đủ nghe để không hại tai; chỉ dùng phần mềm GV đã cài sẵn, không mở phần mềm hay trang khác trong giờ học.","hs":"- HS đọc đúng cao độ “đọc nhạc theo kí hiệu bàn tay” nhờ nghe mẫu từ đàn phím.\n- HS nhận ra ngay nốt mình đọc còn chênh và đọc lại cho đúng."},{"ten":"E. CỦNG CỐ - DẶN DÒ (2 phút)","gv":"- GV hệ thống lại nội dung tiết học, nhận xét tiết học (khen ngợi, nhắc nhở).\n- GV dặn HS về nhà ôn lại bài, tập biểu diễn cho người thân nghe, chuẩn bị bài tiết sau và làm bài trong vở bài tập (nếu có).","hs":"- HS lắng nghe, ghi nhớ.\n- HS hát/đọc nhạc lại một lần để kết thúc tiết học vui vẻ."}],"hotro":"","hoanhap":"","status":"checked","source":"KHBD Âm nhạc 2 KNTT — Bút Xanh (biên soạn tích hợp NLS + AI)"},
{"lop":2,"mon":"Âm nhạc","tuan":11,"tiet":11,"bai":"Chủ đề 3: Mái trường thân yêu — Đọc nhạc: Bài số 2","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Nhớ tên nốt, đọc được cao độ và trường độ bài đọc nhạc số 2 kết hợp kí hiệu bàn tay và nhạc đệm.\n- Biết đọc nhạc kết hợp gõ đệm theo nhịp; cảm nhận yếu tố mạnh – nhẹ.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động tập luyện, mạnh dạn thể hiện bài hát/bài đọc nhạc; tự điều chỉnh khi hát/gõ chưa đúng.\n- Giao tiếp và hợp tác: Biết hát, gõ đệm, vận động theo nhóm; lắng nghe và phối hợp nhịp nhàng cùng bạn.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm hoặc ý tưởng biểu diễn đơn giản.\n3. Phẩm chất\n- Chăm chỉ: Tích cực tham gia các hoạt động ca hát, đọc nhạc, trò chơi âm nhạc.\n- Yêu thích môn Âm nhạc; cảm nhận được vẻ đẹp của âm thanh.\n4. Tích hợp\n- Năng lực số 1.1 CB1 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS đọc đúng cao độ “Bài số 2” nhờ nghe mẫu từ đàn phím.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ cơ bản (thanh phách, song loan, trống con, ma-ra-cát).\n- HS: SGK Âm nhạc 2 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ cơ bản (thanh phách, song loan) nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (4 phút)","gv":"- Trò chơi ôn kí hiệu bàn tay các nốt đã học.","hs":"- HS tham gia trò chơi, đọc nốt theo kí hiệu bàn tay."},{"ten":"B. KHÁM PHÁ - ĐỌC NHẠC (16 phút)","gv":"Mục tiêu: HS đọc đúng bài đọc nhạc số 2.\n- GV giới thiệu bài đọc nhạc số 2, đọc mẫu một lần; hỏi cảm nhận.\n- GV đọc tên nốt từng câu, bắt nhịp HS đọc theo; đọc kết hợp kí hiệu bàn tay.\n- Cho HS đọc với nhiều hình thức: cá nhân/nhóm/tổ/cả lớp.","hs":"- HS nghe đọc mẫu, đọc theo từng câu, kết hợp kí hiệu bàn tay."},{"ten":"C. THỰC HÀNH - LUYỆN TẬP (11 phút)","gv":"Mục tiêu: HS đọc nhạc với nhạc đệm và gõ đệm.\n- GV mở file nhạc đệm, đọc mẫu, HD HS đọc theo.\n- HS đọc nhạc kết hợp gõ đệm theo nhịp và vận động tự do.\n- GV sửa sai, nhắc HS đọc khớp với nhạc đệm.","hs":"- HS đọc nhạc theo nhạc đệm, gõ đệm và vận động."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV dùng đàn phím điện tử hoặc phần mềm đàn phím trên máy tính để lấy cao độ chuẩn cho “Bài số 2”: bấm từng nốt cho HS nghe rõ, bấm chậm cả câu, rồi bấm lại đúng nốt mà HS còn đọc chênh — cao độ lấy từ đàn chuẩn hơn lấy từ giọng người vì không bị lệch theo hơi thở.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV mở trò chơi nghe nốt trên máy: máy phát một nốt, HS giơ kí hiệu bàn tay tương ứng, GV bấm lại nốt đó để cả lớp cùng kiểm tra ngay đúng hay sai rồi đọc lại — HS biết mình sai ở nốt nào ngay tại chỗ chứ không chờ hết giờ.\n⚠ (Miền 4: An toàn) GV thao tác đàn và máy tính, HS chỉ nghe và đọc theo, không tự bấm vào thiết bị của GV; mở âm lượng vừa đủ nghe để không hại tai; chỉ dùng phần mềm GV đã cài sẵn, không mở phần mềm hay trang khác trong giờ học.","hs":"- HS đọc đúng cao độ “Bài số 2” nhờ nghe mẫu từ đàn phím.\n- HS nhận ra ngay nốt mình đọc còn chênh và đọc lại cho đúng."},{"ten":"E. CỦNG CỐ - DẶN DÒ (2 phút)","gv":"- GV hệ thống lại nội dung tiết học, nhận xét tiết học (khen ngợi, nhắc nhở).\n- GV dặn HS về nhà ôn lại bài, tập biểu diễn cho người thân nghe, chuẩn bị bài tiết sau và làm bài trong vở bài tập (nếu có).","hs":"- HS lắng nghe, ghi nhớ.\n- HS hát/đọc nhạc lại một lần để kết thúc tiết học vui vẻ."}],"hotro":"","hoanhap":"","status":"checked","source":"KHBD Âm nhạc 2 KNTT — Bút Xanh (biên soạn tích hợp NLS + AI)"},
{"lop":2,"mon":"Âm nhạc","tuan":12,"tiet":12,"bai":"Chủ đề 3: Mái trường thân yêu — Ôn tập: Hát và Đọc nhạc; Vận dụng – Sáng tạo","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Biểu diễn bài Học sinh lớp Hai chăm ngoan kết hợp vận động; thể hiện bài đọc nhạc số 2 kết hợp gõ đệm.\n- Tham gia trò chơi âm nhạc, sáng tạo động tác vận động đơn giản.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động tập luyện, mạnh dạn thể hiện bài hát/bài đọc nhạc; tự điều chỉnh khi hát/gõ chưa đúng.\n- Giao tiếp và hợp tác: Biết hát, gõ đệm, vận động theo nhóm; lắng nghe và phối hợp nhịp nhàng cùng bạn.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm hoặc ý tưởng biểu diễn đơn giản.\n3. Phẩm chất\n- Chăm chỉ, trách nhiệm.\n- Chăm chỉ: Tích cực tham gia các hoạt động ca hát, đọc nhạc, trò chơi âm nhạc.\n- Yêu thích môn Âm nhạc; cảm nhận được vẻ đẹp của âm thanh.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ cơ bản (thanh phách, song loan, trống con, ma-ra-cát).\n- HS: SGK Âm nhạc 2 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ cơ bản (thanh phách, song loan) nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (4 phút)","gv":"- HS hát lại bài Học sinh lớp Hai chăm ngoan để khởi động.","hs":"- HS hát khởi động."},{"ten":"B. THỰC HÀNH - ÔN TẬP (14 phút)","gv":"Mục tiêu: HS ôn hát và ôn đọc nhạc.\n- Ôn bài hát với nhạc đệm, kết hợp vận động, trình bày theo nhóm.\n- Ôn đọc nhạc số 2 với nhạc đệm ở các hình thức nhóm đọc, nhóm gõ, nhóm vận động.\n- GV góp ý để HS hoàn thiện.","hs":"- HS ôn hát, ôn đọc nhạc; tự nhận xét cho mình và nhóm bạn."},{"ten":"C. VẬN DỤNG - SÁNG TẠO (10 phút)","gv":"Mục tiêu: HS sáng tạo động tác và biểu diễn.\n- HS nghĩ và tập vài động tác phụ hoạ cho bài hát; lên biểu diễn theo nhóm.\n- GV nhận xét, tuyên dương ý tưởng sáng tạo.","hs":"- HS sáng tạo động tác, luyện tập và biểu diễn."},{"ten":"E. CỦNG CỐ - DẶN DÒ (2 phút)","gv":"- GV hệ thống lại nội dung tiết học, nhận xét tiết học (khen ngợi, nhắc nhở).\n- GV dặn HS về nhà ôn lại bài, tập biểu diễn cho người thân nghe, chuẩn bị bài tiết sau và làm bài trong vở bài tập (nếu có).","hs":"- HS lắng nghe, ghi nhớ.\n- HS hát/đọc nhạc lại một lần để kết thúc tiết học vui vẻ."}],"hotro":"","hoanhap":"","status":"checked","source":"KHBD Âm nhạc 2 KNTT — Bút Xanh (biên soạn tích hợp NLS + AI)"},
{"lop":2,"mon":"Âm nhạc","tuan":13,"tiet":13,"bai":"Chủ đề 4: Tuổi thơ — Học hát: Chú chim nhỏ dễ thương (Nhạc: Pháp, lời Việt: Hoàng Anh)","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Hát đúng giai điệu, thuộc lời ca bài Chú chim nhỏ dễ thương; biết bài hát là nhạc Pháp, lời Việt của Hoàng Anh.\n- Hát được giai điệu, lời ca kết hợp gõ đệm theo phách.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động tập luyện, mạnh dạn thể hiện bài hát/bài đọc nhạc; tự điều chỉnh khi hát/gõ chưa đúng.\n- Giao tiếp và hợp tác: Biết hát, gõ đệm, vận động theo nhóm; lắng nghe và phối hợp nhịp nhàng cùng bạn.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm hoặc ý tưởng biểu diễn đơn giản.\n3. Phẩm chất\n- Nhân ái, yêu thiên nhiên: Yêu thiên nhiên và biết bảo vệ các loài động vật.\n- Chăm chỉ: Tích cực tham gia các hoạt động ca hát, đọc nhạc, trò chơi âm nhạc.\n- Yêu thích môn Âm nhạc; cảm nhận được vẻ đẹp của âm thanh.\n4. Tích hợp\n- Năng lực số 1.1 CB1 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS nghe bản thu mẫu và hát đúng lời, đúng cao độ bài “Chú chim nhỏ dễ thương”.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ cơ bản (thanh phách, song loan, trống con, ma-ra-cát).\n- HS: SGK Âm nhạc 2 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ cơ bản (thanh phách, song loan) nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"- GV cho HS hát lại bài Em là học sinh lớp Hai (hoặc bài đã học).\n- Trò chơi: quan sát bức tranh và kể tên loài chim em biết/nghe/nhìn thấy.","hs":"- HS hát khởi động; quan sát tranh, kể tên loài chim."},{"ten":"B. KHÁM PHÁ - HỌC HÁT (15 phút)","gv":"Mục tiêu: HS hát đúng bài Chú chim nhỏ dễ thương.\n- GV giới thiệu bài hát là nhạc Pháp, lời Việt của Hoàng Anh; trình chiếu nước Pháp trên bản đồ.\n- GV đàn + hát mẫu; hỏi tính chất, nhịp điệu bài hát (hơi nhanh, vui).\n- Chia bài thành 6 câu, dạy hát từng câu; luyện hát cho thuộc, chú ý lấy hơi, nhận biết chỗ kết thúc.","hs":"- HS nghe hát mẫu, nêu cảm nhận.\n- HS đọc lời ca, học hát từng câu, luyện hát cho thuộc."},{"ten":"C. THỰC HÀNH - LUYỆN TẬP (10 phút)","gv":"Mục tiêu: HS hát kết hợp gõ đệm và vận động.\n- HD HS hát gõ đệm theo phách vào các bông hoa đỏ, vàng.\n- Tổ chức luyện tập theo nhóm (tổ): mỗi nhóm hát + vỗ tay/gõ đệm một câu; các em sáng tác vài động tác phụ hoạ đơn giản.\n- Gọi nhóm sáng tác xong trước lên biểu diễn; giáo dục yêu và bảo vệ loài vật.","hs":"- HS hát + gõ đệm theo phách; các nhóm sáng tác động tác và biểu diễn."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở bản thu mẫu bài “Chú chim nhỏ dễ thương” lấy từ học liệu điện tử của bộ sách hoặc kênh chính thức của nhà xuất bản, phóng màn hình để cả lớp nhìn thấy tên bài hát, chỉ cho HS dòng ghi tác giả “Nhạc: Pháp, lời Việt: Hoàng Anh”; GV mở từng câu, tạm dừng cho HS nghe kĩ rồi hát theo, câu nào HS hát chênh cao độ thì GV mở lại đúng câu đó.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV dùng điện thoại thu âm phần hát bài “Chú chim nhỏ dễ thương” của cả lớp rồi mở lại ngay cho HS nghe; HS chỉ ra chỗ mình hát to quá, nhỏ quá hoặc sai lời — nghe lại giọng của chính mình là điều hát chay không có được. GV thao tác thiết bị, HS nghe và nhận xét.\n⚠ (Miền 4: An toàn) Bản thu bài “Chú chim nhỏ dễ thương” chỉ lấy từ học liệu của bộ sách hoặc kênh chính thức, không tải nhạc từ trang lạ vì có thể sai lời, sai nhạc và kèm quảng cáo không phù hợp; giới thiệu bài hát phải nói rõ tên tác giả; mở loa vừa đủ nghe, không để loa sát tai HS.","hs":"- HS nghe bản thu mẫu và hát đúng lời, đúng cao độ bài “Chú chim nhỏ dễ thương”.\n- HS nói được tên bài hát cùng tên tác giả; nghe lại bản thu của lớp và chỉ ra một chỗ cần sửa."},{"ten":"E. CỦNG CỐ - DẶN DÒ (2 phút)","gv":"- GV hệ thống lại nội dung tiết học, nhận xét tiết học (khen ngợi, nhắc nhở).\n- GV dặn HS về nhà ôn lại bài, tập biểu diễn cho người thân nghe, chuẩn bị bài tiết sau và làm bài trong vở bài tập (nếu có).","hs":"- HS lắng nghe, ghi nhớ.\n- HS hát/đọc nhạc lại một lần để kết thúc tiết học vui vẻ."}],"hotro":"","hoanhap":"","status":"checked","source":"KHBD Âm nhạc 2 KNTT — Bút Xanh (biên soạn tích hợp NLS + AI)"},
{"lop":2,"mon":"Âm nhạc","tuan":14,"tiet":14,"bai":"Chủ đề 4: Tuổi thơ — Nghe nhạc: Mưa sẽ tạnh thật vui; Ôn tập bài hát: Chú chim nhỏ dễ thương","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Chăm chú nghe và biểu hiện cảm xúc khi nghe bài Mưa sẽ tạnh thật vui; nêu được cảm nhận về tính chất bản nhạc.\n- Hát thuộc bài Chú chim nhỏ dễ thương; hát kết hợp gõ đệm, vận động và gõ hình tiết tấu.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động tập luyện, mạnh dạn thể hiện bài hát/bài đọc nhạc; tự điều chỉnh khi hát/gõ chưa đúng.\n- Giao tiếp và hợp tác: Biết hát, gõ đệm, vận động theo nhóm; lắng nghe và phối hợp nhịp nhàng cùng bạn.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm hoặc ý tưởng biểu diễn đơn giản.\n3. Phẩm chất\n- Nhân ái, lạc quan, yêu thiên nhiên.\n- Chăm chỉ: Tích cực tham gia các hoạt động ca hát, đọc nhạc, trò chơi âm nhạc.\n- Yêu thích môn Âm nhạc; cảm nhận được vẻ đẹp của âm thanh.\n4. Tích hợp\n- Năng lực số 1.1 CB1 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS nghe và xem bản ghi hình “Mưa sẽ tạnh thật vui”, gọi được tên nhạc cụ đang vang lên trên màn hình.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ cơ bản (thanh phách, song loan, trống con, ma-ra-cát).\n- HS: SGK Âm nhạc 2 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ cơ bản (thanh phách, song loan) nếu có.\n- File bài nghe nhạc Mưa sẽ tạnh thật vui.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (4 phút)","gv":"- HS hát lại bài Chú chim nhỏ dễ thương để khởi động.","hs":"- HS hát khởi động."},{"ten":"B. KHÁM PHÁ - NGHE NHẠC (12 phút)","gv":"Mục tiêu: HS nghe và cảm nhận bài Mưa sẽ tạnh thật vui.\n- GV giới thiệu bài hát; cho HS nghe lần 1, hỏi cảm nhận về tốc độ, sắc thái (vui – buồn, nhanh – chậm).\n- Nghe lần 2 kết hợp vận động nhịp nhàng theo bài.\n- GV trò chuyện về nội dung, giáo dục tinh thần lạc quan.","hs":"- HS nghe nhạc, nêu cảm nhận, vận động nhịp nhàng theo bài."},{"ten":"C. THỰC HÀNH - ÔN TẬP BÀI HÁT (11 phút)","gv":"Mục tiêu: HS ôn hát và gõ hình tiết tấu.\n- HS ôn bài Chú chim nhỏ dễ thương với các hình thức tập thể, tổ, cá nhân, kết hợp gõ đệm và vận động.\n- Cùng gõ hình tiết tấu kết hợp đọc từ tượng thanh với trống con.\n- GV nhận xét, sửa sai.","hs":"- HS ôn hát, gõ đệm, vận động; gõ tiết tấu với trống con."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở bản ghi hình buổi biểu diễn tác phẩm “Mưa sẽ tạnh thật vui” để HS vừa nghe vừa nhìn thấy người nghệ sĩ đang chơi nhạc cụ nào, ngồi và cầm đàn ra sao; GV tạm dừng đúng lúc để HS chỉ lên màn hình gọi tên nhạc cụ vừa vang lên.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV cho HS đọc phần chú thích dưới đoạn phim: tên tác phẩm, tên tác giả, tên người biểu diễn; HS hiểu bản nhạc nào cũng do một người viết ra, nhắc đến bản nhạc thì phải gọi đúng tên người ấy.\n⚠ (Miền 4: An toàn) GV chọn và tải sẵn đoạn phim về “Mưa sẽ tạnh thật vui” trước giờ học rồi mở ngoại tuyến để HS không nhìn thấy quảng cáo và các đoạn phim gợi ý bên cạnh; âm lượng để vừa nghe, HS ngồi cách màn hình vừa tầm mắt và không tự thao tác thiết bị.","hs":"- HS nghe và xem bản ghi hình “Mưa sẽ tạnh thật vui”, gọi được tên nhạc cụ đang vang lên trên màn hình.\n- HS nói được tên tác phẩm và tên tác giả có ghi trong phần chú thích."},{"ten":"E. CỦNG CỐ - DẶN DÒ (2 phút)","gv":"- GV hệ thống lại nội dung tiết học, nhận xét tiết học (khen ngợi, nhắc nhở).\n- GV dặn HS về nhà ôn lại bài, tập biểu diễn cho người thân nghe, chuẩn bị bài tiết sau và làm bài trong vở bài tập (nếu có).","hs":"- HS lắng nghe, ghi nhớ.\n- HS hát/đọc nhạc lại một lần để kết thúc tiết học vui vẻ."}],"hotro":"","hoanhap":"","status":"checked","source":"KHBD Âm nhạc 2 KNTT — Bút Xanh (biên soạn tích hợp NLS + AI)"},
{"lop":2,"mon":"Âm nhạc","tuan":15,"tiet":15,"bai":"Chủ đề 4: Tuổi thơ — Nhạc cụ: Dùng nhạc cụ gõ thể hiện hình tiết tấu; Vận dụng – Sáng tạo","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Biết dùng các nhạc cụ gõ (thanh phách, song loan, trống con) thể hiện đúng hình tiết tấu.\n- Biết phối hợp gõ đệm theo nhóm; sáng tạo tiết tấu đơn giản để hoà tấu.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động tập luyện, mạnh dạn thể hiện bài hát/bài đọc nhạc; tự điều chỉnh khi hát/gõ chưa đúng.\n- Giao tiếp và hợp tác: Biết hát, gõ đệm, vận động theo nhóm; lắng nghe và phối hợp nhịp nhàng cùng bạn.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm hoặc ý tưởng biểu diễn đơn giản.\n3. Phẩm chất\n- Chăm chỉ, hợp tác.\n- Chăm chỉ: Tích cực tham gia các hoạt động ca hát, đọc nhạc, trò chơi âm nhạc.\n- Yêu thích môn Âm nhạc; cảm nhận được vẻ đẹp của âm thanh.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ cơ bản (thanh phách, song loan, trống con, ma-ra-cát).\n- HS: SGK Âm nhạc 2 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ cơ bản (thanh phách, song loan) nếu có.\n- Nhạc cụ gõ: thanh phách, song loan, trống con.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (4 phút)","gv":"- Trò chơi gõ đệm theo hình tiết tấu bằng các nhạc cụ gõ đã học.","hs":"- HS gõ đệm theo tiết tấu mẫu."},{"ten":"B. KHÁM PHÁ - LUYỆN TẬP (16 phút)","gv":"Mục tiêu: HS dùng nhạc cụ gõ thể hiện hình tiết tấu.\n- GV giới thiệu hình tiết tấu; đọc mẫu và gõ mẫu bằng thanh phách; HS đọc và gõ theo.\n- HS luyện gõ tiết tấu bằng thanh phách, song loan, trống con.\n- Chia nhóm gõ nối tiếp, hoà tấu các nhạc cụ; GV sửa sai.","hs":"- HS đọc và gõ hình tiết tấu bằng nhiều nhạc cụ; các nhóm hoà tấu."},{"ten":"C. VẬN DỤNG - SÁNG TẠO (11 phút)","gv":"Mục tiêu: HS sáng tạo tiết tấu và hoà tấu.\n- GV gợi ý HS tự tạo một hình tiết tấu đơn giản và gõ thể hiện.\n- Tổ chức hoà tấu nhóm; các nhóm biểu diễn, nhận xét lẫn nhau.","hs":"- HS sáng tạo tiết tấu, luyện tập và hoà tấu theo nhóm."},{"ten":"E. CỦNG CỐ - DẶN DÒ (2 phút)","gv":"- GV hệ thống lại nội dung tiết học, nhận xét tiết học (khen ngợi, nhắc nhở).\n- GV dặn HS về nhà ôn lại bài, tập biểu diễn cho người thân nghe, chuẩn bị bài tiết sau và làm bài trong vở bài tập (nếu có).","hs":"- HS lắng nghe, ghi nhớ.\n- HS hát/đọc nhạc lại một lần để kết thúc tiết học vui vẻ."}],"hotro":"","hoanhap":"","status":"checked","source":"KHBD Âm nhạc 2 KNTT — Bút Xanh (biên soạn tích hợp NLS + AI)"},
{"lop":2,"mon":"Âm nhạc","tuan":16,"tiet":16,"bai":"Chủ đề 4: Tuổi thơ — Ôn tập chủ đề 4; Vận dụng – Sáng tạo","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Biểu diễn thuần thục bài Chú chim nhỏ dễ thương kết hợp gõ đệm, vận động; thể hiện hình tiết tấu với nhạc cụ gõ.\n- Củng cố nội dung chủ đề 4; tham gia trò chơi âm nhạc sáng tạo.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động tập luyện, mạnh dạn thể hiện bài hát/bài đọc nhạc; tự điều chỉnh khi hát/gõ chưa đúng.\n- Giao tiếp và hợp tác: Biết hát, gõ đệm, vận động theo nhóm; lắng nghe và phối hợp nhịp nhàng cùng bạn.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm hoặc ý tưởng biểu diễn đơn giản.\n3. Phẩm chất\n- Nhân ái, chăm chỉ, hợp tác.\n- Chăm chỉ: Tích cực tham gia các hoạt động ca hát, đọc nhạc, trò chơi âm nhạc.\n- Yêu thích môn Âm nhạc; cảm nhận được vẻ đẹp của âm thanh.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ cơ bản (thanh phách, song loan, trống con, ma-ra-cát).\n- HS: SGK Âm nhạc 2 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ cơ bản (thanh phách, song loan) nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (4 phút)","gv":"- Trò chơi nghe giai điệu đoán tên bài hát trong chủ đề.","hs":"- HS lắng nghe và đoán tên bài hát."},{"ten":"B. THỰC HÀNH - ÔN TẬP (14 phút)","gv":"Mục tiêu: HS ôn hát và ôn nhạc cụ gõ.\n- HS biểu diễn bài Chú chim nhỏ dễ thương kết hợp gõ đệm, vận động, phụ hoạ theo nhóm.\n- Ôn thể hiện hình tiết tấu với nhạc cụ gõ; hoà tấu nhóm.\n- GV nhận xét, tuyên dương.","hs":"- HS ôn hát, gõ đệm, hoà tấu; các nhóm biểu diễn."},{"ten":"C. VẬN DỤNG - SÁNG TẠO (10 phút)","gv":"Mục tiêu: HS sáng tạo biểu diễn.\n- Tổ chức thi biểu diễn nhóm kết hợp hát, gõ đệm, vận động phụ hoạ.\n- GV và HS bình chọn, khen ngợi nhóm sáng tạo.","hs":"- HS luyện tập và thi biểu diễn theo nhóm."},{"ten":"E. CỦNG CỐ - DẶN DÒ (2 phút)","gv":"- GV hệ thống lại nội dung tiết học, nhận xét tiết học (khen ngợi, nhắc nhở).\n- GV dặn HS về nhà ôn lại bài, tập biểu diễn cho người thân nghe, chuẩn bị bài tiết sau và làm bài trong vở bài tập (nếu có).","hs":"- HS lắng nghe, ghi nhớ.\n- HS hát/đọc nhạc lại một lần để kết thúc tiết học vui vẻ."}],"hotro":"","hoanhap":"","status":"checked","source":"KHBD Âm nhạc 2 KNTT — Bút Xanh (biên soạn tích hợp NLS + AI)"},
{"lop":2,"mon":"Âm nhạc","tuan":17,"tiet":17,"bai":"Ôn tập cuối học kì I (Tiết 1)","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Hát thuộc, biểu diễn được các bài hát đã học ở học kì I: Dàn nhạc trong vườn, Con chim chích choè, Học sinh lớp Hai chăm ngoan, Chú chim nhỏ dễ thương.\n- Đọc được bài đọc nhạc số 1, số 2; nhận biết các nhạc cụ đã học (song loan, đàn bầu).\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động tập luyện, mạnh dạn thể hiện bài hát/bài đọc nhạc; tự điều chỉnh khi hát/gõ chưa đúng.\n- Giao tiếp và hợp tác: Biết hát, gõ đệm, vận động theo nhóm; lắng nghe và phối hợp nhịp nhàng cùng bạn.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm hoặc ý tưởng biểu diễn đơn giản.\n3. Phẩm chất\n- Chăm chỉ, tự tin biểu diễn.\n- Chăm chỉ: Tích cực tham gia các hoạt động ca hát, đọc nhạc, trò chơi âm nhạc.\n- Yêu thích môn Âm nhạc; cảm nhận được vẻ đẹp của âm thanh.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ cơ bản (thanh phách, song loan, trống con, ma-ra-cát).\n- HS: SGK Âm nhạc 2 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ cơ bản (thanh phách, song loan) nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (4 phút)","gv":"- Trò chơi nghe giai điệu đoán tên bài hát các bài đã học trong học kì I.","hs":"- HS lắng nghe và đoán tên bài hát."},{"ten":"B. THỰC HÀNH - ÔN TẬP BÀI HÁT (14 phút)","gv":"Mục tiêu: HS ôn và biểu diễn các bài hát học kì I.\n- HS ôn lần lượt các bài hát đã học, kết hợp gõ đệm và vận động.\n- Chia nhóm biểu diễn từng bài; GV nhận xét, sửa sai.","hs":"- HS ôn hát, gõ đệm, vận động; các nhóm biểu diễn."},{"ten":"C. THỰC HÀNH - ÔN ĐỌC NHẠC & NHẠC CỤ (10 phút)","gv":"Mục tiêu: HS ôn đọc nhạc và nhận biết nhạc cụ.\n- Ôn bài đọc nhạc số 1, số 2 kết hợp kí hiệu bàn tay, nhạc đệm.\n- Ôn nhận biết song loan, đàn bầu qua hình ảnh/âm thanh.","hs":"- HS ôn đọc nhạc; nhận biết nhạc cụ."},{"ten":"E. CỦNG CỐ - DẶN DÒ (2 phút)","gv":"- GV hệ thống lại nội dung tiết học, nhận xét tiết học (khen ngợi, nhắc nhở).\n- GV dặn HS về nhà ôn lại bài, tập biểu diễn cho người thân nghe, chuẩn bị bài tiết sau và làm bài trong vở bài tập (nếu có).","hs":"- HS lắng nghe, ghi nhớ.\n- HS hát/đọc nhạc lại một lần để kết thúc tiết học vui vẻ."}],"hotro":"","hoanhap":"","status":"checked","source":"KHBD Âm nhạc 2 KNTT — Bút Xanh (biên soạn tích hợp NLS + AI)"},
{"lop":2,"mon":"Âm nhạc","tuan":18,"tiet":18,"bai":"Ôn tập, đánh giá cuối học kì I (Tiết 2)","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Biểu diễn tự tin một bài hát tự chọn ở học kì I kết hợp gõ đệm hoặc vận động; đọc được một bài đọc nhạc.\n- Tự đánh giá và đánh giá bạn về khả năng ca hát, đọc nhạc, gõ đệm.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động tập luyện, mạnh dạn thể hiện bài hát/bài đọc nhạc; tự điều chỉnh khi hát/gõ chưa đúng.\n- Giao tiếp và hợp tác: Biết hát, gõ đệm, vận động theo nhóm; lắng nghe và phối hợp nhịp nhàng cùng bạn.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm hoặc ý tưởng biểu diễn đơn giản.\n3. Phẩm chất\n- Chăm chỉ, tự tin, trung thực khi tự đánh giá.\n- Chăm chỉ: Tích cực tham gia các hoạt động ca hát, đọc nhạc, trò chơi âm nhạc.\n- Yêu thích môn Âm nhạc; cảm nhận được vẻ đẹp của âm thanh.\n4. Tích hợp\n- Năng lực số 3.2 CB1 (Tích hợp và tinh chỉnh nội dung số): HS xem lại đoạn phim phần biểu diễn của tổ và chỉ ra được một chỗ cần sửa.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ cơ bản (thanh phách, song loan, trống con, ma-ra-cát).\n- HS: SGK Âm nhạc 2 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ cơ bản (thanh phách, song loan) nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (4 phút)","gv":"- GV nêu yêu cầu tiết đánh giá; cho HS hát khởi động một bài đã học.","hs":"- HS hát khởi động, nắm yêu cầu đánh giá."},{"ten":"B. THỰC HÀNH - BIỂU DIỄN ĐÁNH GIÁ (16 phút)","gv":"Mục tiêu: HS biểu diễn để GV đánh giá cuối kì.\n- GV tổ chức cho HS (cá nhân/nhóm) biểu diễn một bài hát tự chọn kết hợp gõ đệm hoặc vận động.\n- Mời một số HS đọc một bài đọc nhạc theo kí hiệu bàn tay.\n- GV quan sát, ghi nhận mức độ đạt được của từng HS.","hs":"- HS biểu diễn bài hát, đọc nhạc; các bạn lắng nghe, cổ vũ."},{"ten":"C. VẬN DỤNG - ĐÁNH GIÁ (10 phút)","gv":"Mục tiêu: HS tự đánh giá và đánh giá bạn.\n- GV hướng dẫn HS tự nhận xét phần biểu diễn của mình và của bạn (đúng giai điệu, gõ đệm đều, tự tin).\n- GV tổng kết, khen ngợi, động viên HS cố gắng ở học kì II.","hs":"- HS tự đánh giá và nhận xét bạn; lắng nghe tổng kết của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV dùng điện thoại quay lại phần biểu diễn học kì I của từng tổ rồi mở ngay lên màn hình cho cả lớp cùng xem; HS nhận ra tổ mình đã đứng ngay ngắn chưa, vào bài có đều không, hát đã rõ lời chưa — xem lại chính mình là điều biểu diễn xong rồi kể lại không làm được.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV cho HS làm bộ câu hỏi tương tác có chấm ngay để ôn lại học kì I: nghe một đoạn nhạc rồi chọn đúng tên bài hát, nối tên nhạc cụ với hình, chọn đúng tên tác giả bài hát; sai câu nào GV mở lại đúng đoạn nhạc của câu đó cho HS nghe lại.\n⚠ (Miền 4: An toàn) Đoạn phim quay lớp chỉ mở trong giờ học và trong buổi họp phụ huynh khi cả lớp đồng ý, không đăng lên mạng, không gửi cho người ngoài; bạn nào không muốn bị quay thì GV không quay; nhận xét bạn bằng lời tử tế, không chê bai hình dáng hay giọng hát của bạn.","hs":"- HS xem lại đoạn phim phần biểu diễn của tổ và chỉ ra được một chỗ cần sửa.\n- HS trả lời đúng bộ câu hỏi ôn tập và gọi được tên bài hát, tên tác giả đã học."},{"ten":"E. CỦNG CỐ - DẶN DÒ (2 phút)","gv":"- GV hệ thống lại nội dung tiết học, nhận xét tiết học (khen ngợi, nhắc nhở).\n- GV dặn HS về nhà ôn lại bài, tập biểu diễn cho người thân nghe, chuẩn bị bài tiết sau và làm bài trong vở bài tập (nếu có).","hs":"- HS lắng nghe, ghi nhớ.\n- HS hát/đọc nhạc lại một lần để kết thúc tiết học vui vẻ."}],"hotro":"","hoanhap":"","status":"checked","source":"KHBD Âm nhạc 2 KNTT — Bút Xanh (biên soạn tích hợp NLS + AI)"},
{"lop":2,"mon":"Âm nhạc","tuan":19,"tiet":19,"bai":"Chủ đề 5: Mùa xuân — Học hát: Hoa lá mùa xuân (Nhạc và lời: Hoàng Hà)","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Hát đúng giai điệu, thuộc lời ca bài Hoa lá mùa xuân; thể hiện được tính chất vui tươi, trong sáng của bài hát.\n- Biết hát kết hợp gõ đệm theo phách, theo nhịp.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động tập luyện, mạnh dạn thể hiện bài hát/bài đọc nhạc; tự điều chỉnh khi hát/gõ chưa đúng.\n- Giao tiếp và hợp tác: Biết hát, gõ đệm, vận động theo nhóm; lắng nghe và phối hợp nhịp nhàng cùng bạn.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm hoặc ý tưởng biểu diễn đơn giản.\n3. Phẩm chất\n- Nhân ái, yêu thiên nhiên: Yêu vẻ đẹp mùa xuân, yêu cây cỏ hoa lá quê hương.\n- Chăm chỉ: Tích cực tham gia các hoạt động ca hát, đọc nhạc, trò chơi âm nhạc.\n- Yêu thích môn Âm nhạc; cảm nhận được vẻ đẹp của âm thanh.\n4. Tích hợp\n- Năng lực số 1.1 CB1 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS nghe bản thu mẫu và hát đúng lời, đúng cao độ bài “Hoa lá mùa xuân”.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ cơ bản (thanh phách, song loan, trống con, ma-ra-cát).\n- HS: SGK Âm nhạc 2 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ cơ bản (thanh phách, song loan) nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"- GV giới thiệu chủ đề Mùa xuân; cho HS xem tranh cảnh mùa xuân (hoa lá, cây cối đâm chồi).\n- Trò chơi: kể tên các loài hoa, cây mùa xuân mà em biết theo tiết tấu.","hs":"- HS quan sát tranh, kể tên hoa lá mùa xuân; tham gia trò chơi vui vẻ."},{"ten":"B. KHÁM PHÁ - HỌC HÁT (15 phút)","gv":"Mục tiêu: HS hát đúng bài Hoa lá mùa xuân.\n- GV giới thiệu bài hát của nhạc sĩ Hoàng Hà, nói về cảnh sắc thiên nhiên tươi đẹp khi mùa xuân về.\n- GV hát mẫu (hoặc mở file); hỏi cảm nhận về tính chất bài hát (vui tươi, trong sáng).\n- Hướng dẫn đọc lời ca theo tiết tấu, chia câu; dạy hát nối tiếp từng câu; nhắc HS lấy hơi đầu câu; luyện hát cho thuộc.","hs":"- HS nghe hát mẫu, nêu cảm nhận.\n- HS đọc lời ca, học hát từng câu, luyện hát cho thuộc."},{"ten":"C. THỰC HÀNH - LUYỆN TẬP (10 phút)","gv":"Mục tiêu: HS hát kết hợp gõ đệm theo phách.\n- GV hát và gõ đệm mẫu theo phách.\n- HS hát kết hợp gõ đệm theo phách với các hình thức tập thể, tổ, cá nhân.\n- GV nhận xét, sửa sai; giáo dục HS yêu thiên nhiên, mùa xuân.","hs":"- HS hát + gõ đệm theo phách; các tổ, cá nhân thực hiện."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở bản thu mẫu bài “Hoa lá mùa xuân” lấy từ học liệu điện tử của bộ sách hoặc kênh chính thức của nhà xuất bản, phóng màn hình để cả lớp nhìn thấy tên bài hát, chỉ cho HS dòng ghi tác giả “Nhạc và lời: Hoàng Hà”; GV mở từng câu, tạm dừng cho HS nghe kĩ rồi hát theo, câu nào HS hát chênh cao độ thì GV mở lại đúng câu đó.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV dùng điện thoại thu âm phần hát bài “Hoa lá mùa xuân” của cả lớp rồi mở lại ngay cho HS nghe; HS chỉ ra chỗ mình hát to quá, nhỏ quá hoặc sai lời — nghe lại giọng của chính mình là điều hát chay không có được. GV thao tác thiết bị, HS nghe và nhận xét.\n⚠ (Miền 4: An toàn) Bản thu bài “Hoa lá mùa xuân” chỉ lấy từ học liệu của bộ sách hoặc kênh chính thức, không tải nhạc từ trang lạ vì có thể sai lời, sai nhạc và kèm quảng cáo không phù hợp; giới thiệu bài hát phải nói rõ tên tác giả; mở loa vừa đủ nghe, không để loa sát tai HS.","hs":"- HS nghe bản thu mẫu và hát đúng lời, đúng cao độ bài “Hoa lá mùa xuân”.\n- HS nói được tên bài hát cùng tên tác giả; nghe lại bản thu của lớp và chỉ ra một chỗ cần sửa."},{"ten":"E. CỦNG CỐ - DẶN DÒ (2 phút)","gv":"- GV hệ thống lại nội dung tiết học, nhận xét tiết học (khen ngợi, nhắc nhở).\n- GV dặn HS về nhà ôn lại bài, tập biểu diễn cho người thân nghe, chuẩn bị bài tiết sau và làm bài trong vở bài tập (nếu có).","hs":"- HS lắng nghe, ghi nhớ.\n- HS hát/đọc nhạc lại một lần để kết thúc tiết học vui vẻ."}],"hotro":"","hoanhap":"","status":"checked","source":"KHBD Âm nhạc 2 KNTT — Bút Xanh (biên soạn tích hợp NLS + AI)"},
{"lop":2,"mon":"Âm nhạc","tuan":20,"tiet":20,"bai":"Chủ đề 5: Mùa xuân — Ôn tập bài hát: Hoa lá mùa xuân; Đọc nhạc: Bài số 3","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Hát thuộc bài Hoa lá mùa xuân, hát kết hợp vận động phụ hoạ.\n- Đọc được cao độ, tên nốt bài đọc nhạc số 3 kết hợp kí hiệu bàn tay và nhạc đệm.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động tập luyện, mạnh dạn thể hiện bài hát/bài đọc nhạc; tự điều chỉnh khi hát/gõ chưa đúng.\n- Giao tiếp và hợp tác: Biết hát, gõ đệm, vận động theo nhóm; lắng nghe và phối hợp nhịp nhàng cùng bạn.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm hoặc ý tưởng biểu diễn đơn giản.\n3. Phẩm chất\n- Nhân ái, chăm chỉ.\n- Chăm chỉ: Tích cực tham gia các hoạt động ca hát, đọc nhạc, trò chơi âm nhạc.\n- Yêu thích môn Âm nhạc; cảm nhận được vẻ đẹp của âm thanh.\n4. Tích hợp\n- Năng lực số 1.1 CB1 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS đọc đúng cao độ “Bài số 3” nhờ nghe mẫu từ đàn phím.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ cơ bản (thanh phách, song loan, trống con, ma-ra-cát).\n- HS: SGK Âm nhạc 2 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ cơ bản (thanh phách, song loan) nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (4 phút)","gv":"- HS hát lại bài Hoa lá mùa xuân để khởi động.","hs":"- HS hát khởi động."},{"ten":"B. THỰC HÀNH - ÔN TẬP BÀI HÁT (11 phút)","gv":"Mục tiêu: HS ôn hát và vận động phụ hoạ.\n- HS ôn bài Hoa lá mùa xuân với nhạc đệm, kết hợp vận động phụ hoạ nhịp nhàng.\n- Trình bày theo nhóm hát, nhóm gõ, nhóm vận động; GV nhận xét, hoàn thiện.","hs":"- HS ôn hát, vận động phụ hoạ; trình bày theo nhóm."},{"ten":"C. KHÁM PHÁ - ĐỌC NHẠC BÀI SỐ 3 (13 phút)","gv":"Mục tiêu: HS đọc đúng bài đọc nhạc số 3.\n- GV giới thiệu bài đọc nhạc số 3, đọc mẫu; đọc tên nốt từng câu, HS đọc theo.\n- Đọc kết hợp kí hiệu bàn tay và nhạc đệm; đọc với nhiều hình thức: cá nhân/nhóm/tổ/cả lớp.","hs":"- HS nghe đọc mẫu, đọc theo từng câu, kết hợp kí hiệu bàn tay và nhạc đệm."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV dùng đàn phím điện tử hoặc phần mềm đàn phím trên máy tính để lấy cao độ chuẩn cho “Bài số 3”: bấm từng nốt cho HS nghe rõ, bấm chậm cả câu, rồi bấm lại đúng nốt mà HS còn đọc chênh — cao độ lấy từ đàn chuẩn hơn lấy từ giọng người vì không bị lệch theo hơi thở.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV mở trò chơi nghe nốt trên máy: máy phát một nốt, HS giơ kí hiệu bàn tay tương ứng, GV bấm lại nốt đó để cả lớp cùng kiểm tra ngay đúng hay sai rồi đọc lại — HS biết mình sai ở nốt nào ngay tại chỗ chứ không chờ hết giờ.\n⚠ (Miền 4: An toàn) GV thao tác đàn và máy tính, HS chỉ nghe và đọc theo, không tự bấm vào thiết bị của GV; mở âm lượng vừa đủ nghe để không hại tai; chỉ dùng phần mềm GV đã cài sẵn, không mở phần mềm hay trang khác trong giờ học.","hs":"- HS đọc đúng cao độ “Bài số 3” nhờ nghe mẫu từ đàn phím.\n- HS nhận ra ngay nốt mình đọc còn chênh và đọc lại cho đúng."},{"ten":"E. CỦNG CỐ - DẶN DÒ (2 phút)","gv":"- GV hệ thống lại nội dung tiết học, nhận xét tiết học (khen ngợi, nhắc nhở).\n- GV dặn HS về nhà ôn lại bài, tập biểu diễn cho người thân nghe, chuẩn bị bài tiết sau và làm bài trong vở bài tập (nếu có).","hs":"- HS lắng nghe, ghi nhớ.\n- HS hát/đọc nhạc lại một lần để kết thúc tiết học vui vẻ."}],"hotro":"","hoanhap":"","status":"checked","source":"KHBD Âm nhạc 2 KNTT — Bút Xanh (biên soạn tích hợp NLS + AI)"},
{"lop":2,"mon":"Âm nhạc","tuan":21,"tiet":21,"bai":"Chủ đề 5: Mùa xuân — Thường thức âm nhạc: Câu chuyện về bài hát Chú voi con ở Bản Đôn; Vận dụng – Sáng tạo","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Nhớ và hiểu nội dung câu chuyện về bài hát Chú voi con ở Bản Đôn; chăm chú nghe và biểu hiện cảm xúc khi nghe bài hát.\n- Vận dụng gõ đệm, vận động theo bài hát đã học một cách sáng tạo.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động tập luyện, mạnh dạn thể hiện bài hát/bài đọc nhạc; tự điều chỉnh khi hát/gõ chưa đúng.\n- Giao tiếp và hợp tác: Biết hát, gõ đệm, vận động theo nhóm; lắng nghe và phối hợp nhịp nhàng cùng bạn.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm hoặc ý tưởng biểu diễn đơn giản.\n3. Phẩm chất\n- Nhân ái, yêu thiên nhiên: Yêu vẻ đẹp mùa xuân, yêu cây cỏ hoa lá quê hương.\n- Chăm chỉ: Tích cực tham gia các hoạt động ca hát, đọc nhạc, trò chơi âm nhạc.\n- Yêu thích môn Âm nhạc; cảm nhận được vẻ đẹp của âm thanh.\n4. Tích hợp\n- Năng lực số 1.1 CB1 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS nêu được đặc điểm nổi bật của “Câu chuyện về bài hát Chú voi con ở Bản Đôn” nhờ quan sát tư liệu số và nghe bản thu.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ cơ bản (thanh phách, song loan, trống con, ma-ra-cát).\n- HS: SGK Âm nhạc 2 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ cơ bản (thanh phách, song loan) nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (4 phút)","gv":"- HS hát lại bài Hoa lá mùa xuân kết hợp gõ đệm để khởi động.","hs":"- HS hát và gõ đệm khởi động."},{"ten":"B. KHÁM PHÁ - THƯỜNG THỨC ÂM NHẠC (16 phút)","gv":"Mục tiêu: HS nghe và hiểu câu chuyện về bài hát Chú voi con ở Bản Đôn.\n- GV kể câu chuyện về bài hát Chú voi con ở Bản Đôn theo tranh; gợi ý HS trả lời và kể lại các chi tiết.\n- GV cho HS nghe bài hát Chú voi con ở Bản Đôn; hỏi cảm nhận về tính chất bài hát (vui tươi, hồn nhiên).\n- Cho HS nghe lần 2 kết hợp vận động nhịp nhàng theo bài; giáo dục HS yêu quý loài vật, quê hương.","hs":"- HS nghe kể chuyện, trả lời và kể lại theo tranh.\n- HS nghe bài hát, nêu cảm nhận, vận động nhịp nhàng."},{"ten":"C. VẬN DỤNG - SÁNG TẠO (11 phút)","gv":"Mục tiêu: HS vận dụng gõ đệm, vận động sáng tạo.\n- HS ôn bài Hoa lá mùa xuân kết hợp gõ đệm và tự nghĩ vài động tác phụ hoạ đơn giản.\n- Tổ chức biểu diễn theo nhóm; GV khen ngợi ý tưởng sáng tạo.","hs":"- HS sáng tạo động tác, luyện tập và biểu diễn theo nhóm."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở bản kể chuyện có nhạc minh hoạ cho “Câu chuyện về bài hát Chú voi con ở Bản Đôn”, dừng lại ở mỗi lần một nhân vật xuất hiện để HS nghe kĩ nhạc cụ nào đang thay lời nhân vật đó; nhờ nghe đi nghe lại đúng đoạn, HS nhận ra âm nhạc đang kể chuyện chứ không chỉ làm nền.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) HS làm bài tập tương tác có chấm ngay về “Câu chuyện về bài hát Chú voi con ở Bản Đôn”: nghe đoạn nhạc rồi chọn đúng nhân vật, sắp lại thứ tự diễn biến câu chuyện; sai chỗ nào HS nghe lại đúng đoạn nhạc đó rồi chọn lần nữa.\n⚠ (Miền 4: An toàn) Tư liệu về “Câu chuyện về bài hát Chú voi con ở Bản Đôn” phải lấy từ trang của nhà xuất bản, nhà hát, bảo tàng hoặc kênh chính thức của nghệ sĩ và tải sẵn về máy trước giờ lên lớp để không lẫn quảng cáo; khi kể lại cho người khác phải nói rõ mình đã xem ở đâu, không nhận tư liệu của người khác là của mình; mở âm lượng vừa đủ nghe.","hs":"- HS nêu được đặc điểm nổi bật của “Câu chuyện về bài hát Chú voi con ở Bản Đôn” nhờ quan sát tư liệu số và nghe bản thu.\n- HS làm bài tập tương tác, nhận ra âm sắc – nội dung đã học và tự sửa khi chọn sai."},{"ten":"E. CỦNG CỐ - DẶN DÒ (2 phút)","gv":"- GV hệ thống lại nội dung tiết học, nhận xét tiết học (khen ngợi, nhắc nhở).\n- GV dặn HS về nhà ôn lại bài, tập biểu diễn cho người thân nghe, chuẩn bị bài tiết sau và làm bài trong vở bài tập (nếu có).","hs":"- HS lắng nghe, ghi nhớ.\n- HS hát/đọc nhạc lại một lần để kết thúc tiết học vui vẻ."}],"hotro":"","hoanhap":"","status":"checked","source":"KHBD Âm nhạc 2 KNTT — Bút Xanh (biên soạn tích hợp NLS + AI)"},
{"lop":2,"mon":"Âm nhạc","tuan":22,"tiet":22,"bai":"Chủ đề 5: Mùa xuân — Ôn tập chủ đề 5; Vận dụng – Sáng tạo","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Biểu diễn thuần thục bài Hoa lá mùa xuân kết hợp gõ đệm, vận động; đọc thành thạo bài đọc nhạc số 3.\n- Củng cố nội dung chủ đề 5; tham gia trò chơi âm nhạc sáng tạo.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động tập luyện, mạnh dạn thể hiện bài hát/bài đọc nhạc; tự điều chỉnh khi hát/gõ chưa đúng.\n- Giao tiếp và hợp tác: Biết hát, gõ đệm, vận động theo nhóm; lắng nghe và phối hợp nhịp nhàng cùng bạn.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm hoặc ý tưởng biểu diễn đơn giản.\n3. Phẩm chất\n- Chăm chỉ, hợp tác, tự tin biểu diễn.\n- Chăm chỉ: Tích cực tham gia các hoạt động ca hát, đọc nhạc, trò chơi âm nhạc.\n- Yêu thích môn Âm nhạc; cảm nhận được vẻ đẹp của âm thanh.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ cơ bản (thanh phách, song loan, trống con, ma-ra-cát).\n- HS: SGK Âm nhạc 2 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ cơ bản (thanh phách, song loan) nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (4 phút)","gv":"- Trò chơi nghe giai điệu đoán tên bài hát, bài đọc nhạc đã học trong chủ đề.","hs":"- HS lắng nghe và đoán tên bài hát/bài đọc nhạc."},{"ten":"B. THỰC HÀNH - ÔN TẬP (14 phút)","gv":"Mục tiêu: HS ôn hát và ôn đọc nhạc.\n- HS biểu diễn bài Hoa lá mùa xuân kết hợp gõ đệm, vận động phụ hoạ theo nhóm.\n- Ôn đọc nhạc số 3 với nhạc đệm ở các hình thức nhóm đọc, nhóm gõ, nhóm vận động.\n- GV nhận xét, tuyên dương.","hs":"- HS ôn hát, ôn đọc nhạc; các nhóm biểu diễn và nhận xét lẫn nhau."},{"ten":"C. VẬN DỤNG - SÁNG TẠO (10 phút)","gv":"Mục tiêu: HS sáng tạo biểu diễn.\n- Tổ chức thi biểu diễn nhóm kết hợp hát, gõ đệm, vận động phụ hoạ.\n- GV và HS bình chọn, khen ngợi nhóm sáng tạo.","hs":"- HS luyện tập và thi biểu diễn theo nhóm."},{"ten":"E. CỦNG CỐ - DẶN DÒ (2 phút)","gv":"- GV hệ thống lại nội dung tiết học, nhận xét tiết học (khen ngợi, nhắc nhở).\n- GV dặn HS về nhà ôn lại bài, tập biểu diễn cho người thân nghe, chuẩn bị bài tiết sau và làm bài trong vở bài tập (nếu có).","hs":"- HS lắng nghe, ghi nhớ.\n- HS hát/đọc nhạc lại một lần để kết thúc tiết học vui vẻ."}],"hotro":"","hoanhap":"","status":"checked","source":"KHBD Âm nhạc 2 KNTT — Bút Xanh (biên soạn tích hợp NLS + AI)"},
{"lop":2,"mon":"Âm nhạc","tuan":23,"tiet":23,"bai":"Chủ đề 6: Gia đình yêu thương — Học hát: Mẹ ơi có biết (Nhạc và lời: Nguyễn Văn Chung)","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Hát đúng giai điệu, thuộc lời ca bài Mẹ ơi có biết; thể hiện tình cảm tha thiết, trìu mến của bài hát.\n- Biết hát kết hợp gõ đệm theo phách, theo nhịp.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động tập luyện, mạnh dạn thể hiện bài hát/bài đọc nhạc; tự điều chỉnh khi hát/gõ chưa đúng.\n- Giao tiếp và hợp tác: Biết hát, gõ đệm, vận động theo nhóm; lắng nghe và phối hợp nhịp nhàng cùng bạn.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm hoặc ý tưởng biểu diễn đơn giản.\n3. Phẩm chất\n- Nhân ái, biết ơn: Yêu thương, kính trọng và biết ơn ông bà, cha mẹ.\n- Chăm chỉ: Tích cực tham gia các hoạt động ca hát, đọc nhạc, trò chơi âm nhạc.\n- Yêu thích môn Âm nhạc; cảm nhận được vẻ đẹp của âm thanh.\n4. Tích hợp\n- Năng lực số 1.1 CB1 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS nghe bản thu mẫu và hát đúng lời, đúng cao độ bài “Mẹ ơi có biết”.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ cơ bản (thanh phách, song loan, trống con, ma-ra-cát).\n- HS: SGK Âm nhạc 2 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ cơ bản (thanh phách, song loan) nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"- GV giới thiệu chủ đề Gia đình yêu thương; cho HS xem tranh về gia đình, trò chuyện về tình cảm với mẹ, với gia đình.","hs":"- HS quan sát tranh, chia sẻ về gia đình và tình cảm với mẹ."},{"ten":"B. KHÁM PHÁ - HỌC HÁT (15 phút)","gv":"Mục tiêu: HS hát đúng bài Mẹ ơi có biết.\n- GV giới thiệu bài hát của nhạc sĩ Nguyễn Văn Chung, nói về tình yêu thương của con dành cho mẹ.\n- GV hát mẫu (hoặc mở file); hỏi cảm nhận về tính chất bài hát (tha thiết, trìu mến).\n- Hướng dẫn đọc lời ca theo tiết tấu, chia câu; dạy hát nối tiếp từng câu; nhắc HS hát nhẹ nhàng, tình cảm; luyện hát cho thuộc.","hs":"- HS nghe hát mẫu, nêu cảm nhận.\n- HS đọc lời ca, học hát từng câu, luyện hát cho thuộc."},{"ten":"C. THỰC HÀNH - LUYỆN TẬP (10 phút)","gv":"Mục tiêu: HS hát kết hợp gõ đệm theo phách.\n- GV hát và gõ đệm mẫu theo phách.\n- HS hát kết hợp gõ đệm theo phách với các hình thức tập thể, tổ, cá nhân.\n- GV nhận xét, sửa sai; giáo dục HS biết yêu thương, biết ơn ông bà, cha mẹ.","hs":"- HS hát + gõ đệm theo phách; các tổ, cá nhân thực hiện."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở bản thu mẫu bài “Mẹ ơi có biết” lấy từ học liệu điện tử của bộ sách hoặc kênh chính thức của nhà xuất bản, phóng màn hình để cả lớp nhìn thấy tên bài hát, chỉ cho HS dòng ghi tác giả “Nhạc và lời: Nguyễn Văn Chung”; GV mở từng câu, tạm dừng cho HS nghe kĩ rồi hát theo, câu nào HS hát chênh cao độ thì GV mở lại đúng câu đó.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV dùng điện thoại thu âm phần hát bài “Mẹ ơi có biết” của cả lớp rồi mở lại ngay cho HS nghe; HS chỉ ra chỗ mình hát to quá, nhỏ quá hoặc sai lời — nghe lại giọng của chính mình là điều hát chay không có được. GV thao tác thiết bị, HS nghe và nhận xét.\n⚠ (Miền 4: An toàn) Bản thu bài “Mẹ ơi có biết” chỉ lấy từ học liệu của bộ sách hoặc kênh chính thức, không tải nhạc từ trang lạ vì có thể sai lời, sai nhạc và kèm quảng cáo không phù hợp; giới thiệu bài hát phải nói rõ tên tác giả; mở loa vừa đủ nghe, không để loa sát tai HS.","hs":"- HS nghe bản thu mẫu và hát đúng lời, đúng cao độ bài “Mẹ ơi có biết”.\n- HS nói được tên bài hát cùng tên tác giả; nghe lại bản thu của lớp và chỉ ra một chỗ cần sửa."},{"ten":"E. CỦNG CỐ - DẶN DÒ (2 phút)","gv":"- GV hệ thống lại nội dung tiết học, nhận xét tiết học (khen ngợi, nhắc nhở).\n- GV dặn HS về nhà ôn lại bài, tập biểu diễn cho người thân nghe, chuẩn bị bài tiết sau và làm bài trong vở bài tập (nếu có).","hs":"- HS lắng nghe, ghi nhớ.\n- HS hát/đọc nhạc lại một lần để kết thúc tiết học vui vẻ."}],"hotro":"","hoanhap":"","status":"checked","source":"KHBD Âm nhạc 2 KNTT — Bút Xanh (biên soạn tích hợp NLS + AI)"},
{"lop":2,"mon":"Âm nhạc","tuan":24,"tiet":24,"bai":"Chủ đề 6: Gia đình yêu thương — Ôn tập bài hát: Mẹ ơi có biết; Nghe nhạc: Ru con","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Hát thuộc bài Mẹ ơi có biết; hát kết hợp gõ đệm và vận động phụ hoạ.\n- Chăm chú nghe và biểu hiện cảm xúc khi nghe bài Ru con; nêu được cảm nhận về tính chất êm dịu của bài hát.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động tập luyện, mạnh dạn thể hiện bài hát/bài đọc nhạc; tự điều chỉnh khi hát/gõ chưa đúng.\n- Giao tiếp và hợp tác: Biết hát, gõ đệm, vận động theo nhóm; lắng nghe và phối hợp nhịp nhàng cùng bạn.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm hoặc ý tưởng biểu diễn đơn giản.\n3. Phẩm chất\n- Nhân ái, biết ơn: Yêu thương, kính trọng và biết ơn ông bà, cha mẹ.\n- Chăm chỉ: Tích cực tham gia các hoạt động ca hát, đọc nhạc, trò chơi âm nhạc.\n- Yêu thích môn Âm nhạc; cảm nhận được vẻ đẹp của âm thanh.\n4. Tích hợp\n- Năng lực số 1.1 CB1 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS nghe và xem bản ghi hình “Ru con”, gọi được tên nhạc cụ đang vang lên trên màn hình.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ cơ bản (thanh phách, song loan, trống con, ma-ra-cát).\n- HS: SGK Âm nhạc 2 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ cơ bản (thanh phách, song loan) nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (4 phút)","gv":"- HS hát lại bài Mẹ ơi có biết để khởi động.","hs":"- HS hát khởi động."},{"ten":"B. THỰC HÀNH - ÔN TẬP BÀI HÁT (11 phút)","gv":"Mục tiêu: HS ôn hát và vận động phụ hoạ.\n- HS ôn bài Mẹ ơi có biết với nhạc đệm, kết hợp gõ đệm và vận động phụ hoạ nhẹ nhàng.\n- Trình bày theo nhóm hát, nhóm gõ, nhóm vận động; GV nhận xét.","hs":"- HS ôn hát, gõ đệm, vận động phụ hoạ; trình bày theo nhóm."},{"ten":"C. KHÁM PHÁ - NGHE NHẠC (13 phút)","gv":"Mục tiêu: HS nghe và cảm nhận bài Ru con.\n- GV giới thiệu bài Ru con (làn điệu ru quen thuộc); cho HS nghe lần 1, hỏi cảm nhận về tốc độ, sắc thái (êm dịu, nhẹ nhàng).\n- Nghe lần 2 kết hợp đung đưa nhịp nhàng theo bài.\n- GV trò chuyện về nội dung, giáo dục tình cảm gia đình, biết ơn cha mẹ.","hs":"- HS nghe nhạc, nêu cảm nhận, đung đưa nhịp nhàng theo bài."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở bản ghi hình buổi biểu diễn tác phẩm “Ru con” để HS vừa nghe vừa nhìn thấy người nghệ sĩ đang chơi nhạc cụ nào, ngồi và cầm đàn ra sao; GV tạm dừng đúng lúc để HS chỉ lên màn hình gọi tên nhạc cụ vừa vang lên.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV cho HS đọc phần chú thích dưới đoạn phim: tên tác phẩm, tên tác giả, tên người biểu diễn; HS hiểu bản nhạc nào cũng do một người viết ra, nhắc đến bản nhạc thì phải gọi đúng tên người ấy.\n⚠ (Miền 4: An toàn) GV chọn và tải sẵn đoạn phim về “Ru con” trước giờ học rồi mở ngoại tuyến để HS không nhìn thấy quảng cáo và các đoạn phim gợi ý bên cạnh; âm lượng để vừa nghe, HS ngồi cách màn hình vừa tầm mắt và không tự thao tác thiết bị.","hs":"- HS nghe và xem bản ghi hình “Ru con”, gọi được tên nhạc cụ đang vang lên trên màn hình.\n- HS nói được tên tác phẩm và tên tác giả có ghi trong phần chú thích."},{"ten":"E. CỦNG CỐ - DẶN DÒ (2 phút)","gv":"- GV hệ thống lại nội dung tiết học, nhận xét tiết học (khen ngợi, nhắc nhở).\n- GV dặn HS về nhà ôn lại bài, tập biểu diễn cho người thân nghe, chuẩn bị bài tiết sau và làm bài trong vở bài tập (nếu có).","hs":"- HS lắng nghe, ghi nhớ.\n- HS hát/đọc nhạc lại một lần để kết thúc tiết học vui vẻ."}],"hotro":"","hoanhap":"","status":"checked","source":"KHBD Âm nhạc 2 KNTT — Bút Xanh (biên soạn tích hợp NLS + AI)"},
{"lop":2,"mon":"Âm nhạc","tuan":25,"tiet":25,"bai":"Chủ đề 6: Gia đình yêu thương — Thường thức âm nhạc: Giới thiệu nhạc cụ Ma-ra-cát; Vận dụng – Sáng tạo","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Nhận biết nhạc cụ gõ ma-ra-cát; biết cách cầm, cách chơi và dùng ma-ra-cát gõ đệm theo tiết tấu, theo bài hát.\n- Vận dụng gõ đệm bằng ma-ra-cát vào bài hát đã học.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động tập luyện, mạnh dạn thể hiện bài hát/bài đọc nhạc; tự điều chỉnh khi hát/gõ chưa đúng.\n- Giao tiếp và hợp tác: Biết hát, gõ đệm, vận động theo nhóm; lắng nghe và phối hợp nhịp nhàng cùng bạn.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm hoặc ý tưởng biểu diễn đơn giản.\n3. Phẩm chất\n- Chăm chỉ, yêu âm nhạc, hợp tác.\n- Chăm chỉ: Tích cực tham gia các hoạt động ca hát, đọc nhạc, trò chơi âm nhạc.\n- Yêu thích môn Âm nhạc; cảm nhận được vẻ đẹp của âm thanh.\n4. Tích hợp\n- Năng lực số 1.1 CB1 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS nêu được đặc điểm nổi bật của “Giới thiệu nhạc cụ Ma-ra-cát” nhờ quan sát tư liệu số và nghe bản thu.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ cơ bản (thanh phách, song loan, trống con, ma-ra-cát).\n- HS: SGK Âm nhạc 2 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ cơ bản (thanh phách, song loan) nếu có.\n- Nhạc cụ ma-ra-cát (thật hoặc hình ảnh/video).","hoatdong":[{"ten":"A. KHỞI ĐỘNG (4 phút)","gv":"- HS hát lại bài Mẹ ơi có biết kết hợp gõ đệm để khởi động.","hs":"- HS hát và gõ đệm khởi động."},{"ten":"B. KHÁM PHÁ - NHẠC CỤ MA-RA-CÁT (16 phút)","gv":"Mục tiêu: HS nhận biết và sử dụng nhạc cụ ma-ra-cát.\n- GV giới thiệu, hướng dẫn HS cách cầm, cách chơi và âm thanh của ma-ra-cát (lắc đều, đúng tư thế).\n- GV gõ/lắc âm thanh cho HS nghe, HD lắc tự do cho quen tay.\n- HS luyện gõ theo hình tiết tấu; dùng ma-ra-cát gõ đệm theo phách vào bài Mẹ ơi có biết.\n- Luyện tập/trình bày (gõ đệm, hát) theo cá nhân, cặp, nhóm.","hs":"- HS quan sát, lắng nghe, tập cầm và lắc ma-ra-cát.\n- HS luyện tiết tấu, gõ đệm vào bài hát; trình bày theo nhóm."},{"ten":"C. VẬN DỤNG - SÁNG TẠO (11 phút)","gv":"Mục tiêu: HS vận dụng ma-ra-cát gõ đệm và hoà tấu.\n- GV cho HS phối hợp ma-ra-cát với các nhạc cụ gõ đã học (thanh phách, song loan) để gõ đệm cho bài hát.\n- Chia nhóm hoà tấu; các nhóm biểu diễn, nhận xét lẫn nhau.","hs":"- HS phối hợp gõ đệm, hoà tấu theo nhóm và biểu diễn."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu đoạn phim quay cận cảnh cho nội dung “Giới thiệu nhạc cụ Ma-ra-cát”: nhìn rõ hình dáng, chất liệu, số dây hoặc số lỗ, bàn tay nghệ sĩ đặt ở đâu và làm động tác gì để ra tiếng; GV tua chậm và dừng đúng chỗ đó — chi tiết này tranh in trong sách và một lần nghe trên lớp không cho thấy được.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) HS làm bài tập nghe tương tác có chấm ngay: GV mở lần lượt vài đoạn nhạc ngắn, HS chọn đoạn nào có âm sắc của nhạc cụ vừa học trong “Giới thiệu nhạc cụ Ma-ra-cát”; chọn sai thì nghe lại đoạn đó và chọn lần nữa cho tới khi nhận ra đúng.\n⚠ (Miền 4: An toàn) Tư liệu về “Giới thiệu nhạc cụ Ma-ra-cát” phải lấy từ trang của nhà xuất bản, nhà hát, bảo tàng hoặc kênh chính thức của nghệ sĩ và tải sẵn về máy trước giờ lên lớp để không lẫn quảng cáo; khi kể lại cho người khác phải nói rõ mình đã xem ở đâu, không nhận tư liệu của người khác là của mình; mở âm lượng vừa đủ nghe.","hs":"- HS nêu được đặc điểm nổi bật của “Giới thiệu nhạc cụ Ma-ra-cát” nhờ quan sát tư liệu số và nghe bản thu.\n- HS làm bài tập tương tác, nhận ra âm sắc – nội dung đã học và tự sửa khi chọn sai."},{"ten":"E. CỦNG CỐ - DẶN DÒ (2 phút)","gv":"- GV hệ thống lại nội dung tiết học, nhận xét tiết học (khen ngợi, nhắc nhở).\n- GV dặn HS về nhà ôn lại bài, tập biểu diễn cho người thân nghe, chuẩn bị bài tiết sau và làm bài trong vở bài tập (nếu có).","hs":"- HS lắng nghe, ghi nhớ.\n- HS hát/đọc nhạc lại một lần để kết thúc tiết học vui vẻ."}],"hotro":"","hoanhap":"","status":"checked","source":"KHBD Âm nhạc 2 KNTT — Bút Xanh (biên soạn tích hợp NLS + AI)"},
{"lop":2,"mon":"Âm nhạc","tuan":26,"tiet":26,"bai":"Chủ đề 6: Gia đình yêu thương — Ôn tập chủ đề 6; Vận dụng – Sáng tạo","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Biểu diễn thuần thục bài Mẹ ơi có biết kết hợp gõ đệm, vận động phụ hoạ; sử dụng ma-ra-cát gõ đệm.\n- Củng cố nội dung chủ đề 6; tham gia trò chơi âm nhạc sáng tạo.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động tập luyện, mạnh dạn thể hiện bài hát/bài đọc nhạc; tự điều chỉnh khi hát/gõ chưa đúng.\n- Giao tiếp và hợp tác: Biết hát, gõ đệm, vận động theo nhóm; lắng nghe và phối hợp nhịp nhàng cùng bạn.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm hoặc ý tưởng biểu diễn đơn giản.\n3. Phẩm chất\n- Chăm chỉ, hợp tác, tự tin biểu diễn.\n- Chăm chỉ: Tích cực tham gia các hoạt động ca hát, đọc nhạc, trò chơi âm nhạc.\n- Yêu thích môn Âm nhạc; cảm nhận được vẻ đẹp của âm thanh.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ cơ bản (thanh phách, song loan, trống con, ma-ra-cát).\n- HS: SGK Âm nhạc 2 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ cơ bản (thanh phách, song loan) nếu có.\n- Nhạc cụ ma-ra-cát.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (4 phút)","gv":"- Trò chơi nghe giai điệu đoán tên bài hát đã học trong chủ đề.","hs":"- HS lắng nghe và đoán tên bài hát."},{"ten":"B. THỰC HÀNH - ÔN TẬP (14 phút)","gv":"Mục tiêu: HS biểu diễn bài Mẹ ơi có biết kết hợp gõ đệm, vận động.\n- HS ôn hát với nhiều hình thức; kết hợp vận động phụ hoạ và gõ đệm bằng ma-ra-cát, thanh phách.\n- Chia nhóm biểu diễn: nhóm hát, nhóm gõ đệm, nhóm vận động; luân phiên.\n- GV nhận xét, sửa sai, tuyên dương.","hs":"- HS ôn hát, gõ đệm, vận động; các nhóm biểu diễn và nhận xét lẫn nhau."},{"ten":"C. VẬN DỤNG - SÁNG TẠO (10 phút)","gv":"Mục tiêu: HS sáng tạo động tác và biểu diễn.\n- GV cho HS tự nghĩ và biểu diễn vài động tác phụ hoạ đơn giản cho bài hát.\n- Tổ chức thi biểu diễn nhóm; khen ngợi ý tưởng sáng tạo.","hs":"- HS sáng tạo động tác, luyện tập trong nhóm và lên biểu diễn."},{"ten":"E. CỦNG CỐ - DẶN DÒ (2 phút)","gv":"- GV hệ thống lại nội dung tiết học, nhận xét tiết học (khen ngợi, nhắc nhở).\n- GV dặn HS về nhà ôn lại bài, tập biểu diễn cho người thân nghe, chuẩn bị bài tiết sau và làm bài trong vở bài tập (nếu có).","hs":"- HS lắng nghe, ghi nhớ.\n- HS hát/đọc nhạc lại một lần để kết thúc tiết học vui vẻ."}],"hotro":"","hoanhap":"","status":"checked","source":"KHBD Âm nhạc 2 KNTT — Bút Xanh (biên soạn tích hợp NLS + AI)"},
{"lop":2,"mon":"Âm nhạc","tuan":27,"tiet":27,"bai":"Chủ đề 7: Những con vật quanh em — Học hát: Trang trại vui vẻ (Nhạc nước ngoài, lời Việt)","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Hát đúng giai điệu, thuộc lời ca bài Trang trại vui vẻ; thể hiện tính chất vui nhộn, hồn nhiên của bài hát ở nhịp 2/4.\n- Biết hát kết hợp gõ đệm theo phách, theo tiết tấu lời ca.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động tập luyện, mạnh dạn thể hiện bài hát/bài đọc nhạc; tự điều chỉnh khi hát/gõ chưa đúng.\n- Giao tiếp và hợp tác: Biết hát, gõ đệm, vận động theo nhóm; lắng nghe và phối hợp nhịp nhàng cùng bạn.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm hoặc ý tưởng biểu diễn đơn giản.\n3. Phẩm chất\n- Nhân ái, yêu thiên nhiên: Yêu quý, gần gũi và bảo vệ các loài vật.\n- Chăm chỉ: Tích cực tham gia các hoạt động ca hát, đọc nhạc, trò chơi âm nhạc.\n- Yêu thích môn Âm nhạc; cảm nhận được vẻ đẹp của âm thanh.\n4. Tích hợp\n- Năng lực số 1.1 CB1 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS nghe bản thu mẫu và hát đúng lời, đúng cao độ bài “Trang trại vui vẻ”.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ cơ bản (thanh phách, song loan, trống con, ma-ra-cát).\n- HS: SGK Âm nhạc 2 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ cơ bản (thanh phách, song loan) nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"- GV giới thiệu chủ đề Những con vật quanh em.\n- Trò chơi: bắt chước tiếng kêu các con vật trong trang trại (cừu, vịt, bò, gà…) theo tiết tấu.","hs":"- HS tham gia trò chơi bắt chước tiếng con vật vui vẻ."},{"ten":"B. KHÁM PHÁ - HỌC HÁT (15 phút)","gv":"Mục tiêu: HS hát đúng bài Trang trại vui vẻ.\n- GV giới thiệu bài hát nói về niềm vui khi đến thăm trang trại và làm quen các con vật; bài có tính chất vui nhộn ở nhịp 2/4.\n- GV hát mẫu (hoặc mở file); hỏi cảm nhận về tính chất bài hát.\n- Hướng dẫn đọc lời ca theo tiết tấu, chia câu; dạy hát nối tiếp từng câu; luyện hát cho thuộc.","hs":"- HS nghe hát mẫu, nêu cảm nhận.\n- HS đọc lời ca, học hát từng câu, luyện hát cho thuộc."},{"ten":"C. THỰC HÀNH - LUYỆN TẬP (10 phút)","gv":"Mục tiêu: HS hát kết hợp gõ đệm theo phách và tiết tấu lời ca.\n- GV hát và gõ đệm mẫu theo phách, theo tiết tấu lời ca.\n- HS hát kết hợp gõ đệm với các hình thức tập thể, tổ, cá nhân.\n- GV nhận xét, sửa sai; giáo dục HS yêu quý, chăm sóc các con vật.","hs":"- HS hát + gõ đệm theo phách và tiết tấu lời ca; các tổ, cá nhân thực hiện."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở bản thu mẫu bài “Trang trại vui vẻ” lấy từ học liệu điện tử của bộ sách hoặc kênh chính thức của nhà xuất bản, phóng màn hình để cả lớp nhìn thấy tên bài hát, chỉ cho HS dòng ghi tác giả “Nhạc nước ngoài, lời Việt”; GV mở từng câu, tạm dừng cho HS nghe kĩ rồi hát theo, câu nào HS hát chênh cao độ thì GV mở lại đúng câu đó.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV dùng điện thoại thu âm phần hát bài “Trang trại vui vẻ” của cả lớp rồi mở lại ngay cho HS nghe; HS chỉ ra chỗ mình hát to quá, nhỏ quá hoặc sai lời — nghe lại giọng của chính mình là điều hát chay không có được. GV thao tác thiết bị, HS nghe và nhận xét.\n⚠ (Miền 4: An toàn) Bản thu bài “Trang trại vui vẻ” chỉ lấy từ học liệu của bộ sách hoặc kênh chính thức, không tải nhạc từ trang lạ vì có thể sai lời, sai nhạc và kèm quảng cáo không phù hợp; giới thiệu bài hát phải nói rõ tên tác giả; mở loa vừa đủ nghe, không để loa sát tai HS.","hs":"- HS nghe bản thu mẫu và hát đúng lời, đúng cao độ bài “Trang trại vui vẻ”.\n- HS nói được tên bài hát cùng tên tác giả; nghe lại bản thu của lớp và chỉ ra một chỗ cần sửa."},{"ten":"E. CỦNG CỐ - DẶN DÒ (2 phút)","gv":"- GV hệ thống lại nội dung tiết học, nhận xét tiết học (khen ngợi, nhắc nhở).\n- GV dặn HS về nhà ôn lại bài, tập biểu diễn cho người thân nghe, chuẩn bị bài tiết sau và làm bài trong vở bài tập (nếu có).","hs":"- HS lắng nghe, ghi nhớ.\n- HS hát/đọc nhạc lại một lần để kết thúc tiết học vui vẻ."}],"hotro":"","hoanhap":"","status":"checked","source":"KHBD Âm nhạc 2 KNTT — Bút Xanh (biên soạn tích hợp NLS + AI)"},
{"lop":2,"mon":"Âm nhạc","tuan":28,"tiet":28,"bai":"Chủ đề 7: Những con vật quanh em — Ôn tập bài hát: Trang trại vui vẻ; Đọc nhạc: Bài số 4","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Hát thuộc bài Trang trại vui vẻ, hát kết hợp vận động phụ hoạ.\n- Đọc được cao độ, tên nốt bài đọc nhạc số 4 kết hợp kí hiệu bàn tay và nhạc đệm.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động tập luyện, mạnh dạn thể hiện bài hát/bài đọc nhạc; tự điều chỉnh khi hát/gõ chưa đúng.\n- Giao tiếp và hợp tác: Biết hát, gõ đệm, vận động theo nhóm; lắng nghe và phối hợp nhịp nhàng cùng bạn.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm hoặc ý tưởng biểu diễn đơn giản.\n3. Phẩm chất\n- Nhân ái, chăm chỉ.\n- Chăm chỉ: Tích cực tham gia các hoạt động ca hát, đọc nhạc, trò chơi âm nhạc.\n- Yêu thích môn Âm nhạc; cảm nhận được vẻ đẹp của âm thanh.\n4. Tích hợp\n- Năng lực số 1.1 CB1 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS đọc đúng cao độ “Bài số 4” nhờ nghe mẫu từ đàn phím.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ cơ bản (thanh phách, song loan, trống con, ma-ra-cát).\n- HS: SGK Âm nhạc 2 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ cơ bản (thanh phách, song loan) nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (4 phút)","gv":"- HS hát lại bài Trang trại vui vẻ để khởi động.","hs":"- HS hát khởi động."},{"ten":"B. THỰC HÀNH - ÔN TẬP BÀI HÁT (11 phút)","gv":"Mục tiêu: HS ôn hát và vận động phụ hoạ.\n- HS ôn bài Trang trại vui vẻ với nhạc đệm, kết hợp vận động phụ hoạ, mô phỏng các con vật.\n- Trình bày theo nhóm hát, nhóm gõ, nhóm vận động; GV nhận xét.","hs":"- HS ôn hát, vận động phụ hoạ; trình bày theo nhóm."},{"ten":"C. KHÁM PHÁ - ĐỌC NHẠC BÀI SỐ 4 (13 phút)","gv":"Mục tiêu: HS đọc đúng bài đọc nhạc số 4.\n- GV giới thiệu bài đọc nhạc số 4, đọc mẫu; đọc tên nốt từng câu, HS đọc theo.\n- Đọc kết hợp kí hiệu bàn tay và nhạc đệm; đọc với nhiều hình thức: cá nhân/nhóm/tổ/cả lớp.","hs":"- HS nghe đọc mẫu, đọc theo từng câu, kết hợp kí hiệu bàn tay và nhạc đệm."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV dùng đàn phím điện tử hoặc phần mềm đàn phím trên máy tính để lấy cao độ chuẩn cho “Bài số 4”: bấm từng nốt cho HS nghe rõ, bấm chậm cả câu, rồi bấm lại đúng nốt mà HS còn đọc chênh — cao độ lấy từ đàn chuẩn hơn lấy từ giọng người vì không bị lệch theo hơi thở.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV mở trò chơi nghe nốt trên máy: máy phát một nốt, HS giơ kí hiệu bàn tay tương ứng, GV bấm lại nốt đó để cả lớp cùng kiểm tra ngay đúng hay sai rồi đọc lại — HS biết mình sai ở nốt nào ngay tại chỗ chứ không chờ hết giờ.\n⚠ (Miền 4: An toàn) GV thao tác đàn và máy tính, HS chỉ nghe và đọc theo, không tự bấm vào thiết bị của GV; mở âm lượng vừa đủ nghe để không hại tai; chỉ dùng phần mềm GV đã cài sẵn, không mở phần mềm hay trang khác trong giờ học.","hs":"- HS đọc đúng cao độ “Bài số 4” nhờ nghe mẫu từ đàn phím.\n- HS nhận ra ngay nốt mình đọc còn chênh và đọc lại cho đúng."},{"ten":"E. CỦNG CỐ - DẶN DÒ (2 phút)","gv":"- GV hệ thống lại nội dung tiết học, nhận xét tiết học (khen ngợi, nhắc nhở).\n- GV dặn HS về nhà ôn lại bài, tập biểu diễn cho người thân nghe, chuẩn bị bài tiết sau và làm bài trong vở bài tập (nếu có).","hs":"- HS lắng nghe, ghi nhớ.\n- HS hát/đọc nhạc lại một lần để kết thúc tiết học vui vẻ."}],"hotro":"","hoanhap":"","status":"checked","source":"KHBD Âm nhạc 2 KNTT — Bút Xanh (biên soạn tích hợp NLS + AI)"},
{"lop":2,"mon":"Âm nhạc","tuan":29,"tiet":29,"bai":"Chủ đề 7: Những con vật quanh em — Nghe nhạc: Vũ khúc đàn gà con; Ôn tập bài hát và Đọc nhạc","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Chăm chú nghe và biểu hiện cảm xúc khi nghe bản nhạc Vũ khúc đàn gà con; nêu được cảm nhận về tính chất bản nhạc.\n- Ôn hát Trang trại vui vẻ và ôn đọc nhạc số 4 kết hợp gõ đệm, vận động.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động tập luyện, mạnh dạn thể hiện bài hát/bài đọc nhạc; tự điều chỉnh khi hát/gõ chưa đúng.\n- Giao tiếp và hợp tác: Biết hát, gõ đệm, vận động theo nhóm; lắng nghe và phối hợp nhịp nhàng cùng bạn.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm hoặc ý tưởng biểu diễn đơn giản.\n3. Phẩm chất\n- Nhân ái, yêu thiên nhiên: Yêu quý, gần gũi và bảo vệ các loài vật.\n- Chăm chỉ: Tích cực tham gia các hoạt động ca hát, đọc nhạc, trò chơi âm nhạc.\n- Yêu thích môn Âm nhạc; cảm nhận được vẻ đẹp của âm thanh.\n4. Tích hợp\n- Năng lực số 1.1 CB1 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS nghe và xem bản ghi hình “Vũ khúc đàn gà con”, gọi được tên nhạc cụ đang vang lên trên màn hình.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ cơ bản (thanh phách, song loan, trống con, ma-ra-cát).\n- HS: SGK Âm nhạc 2 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ cơ bản (thanh phách, song loan) nếu có.\n- File bản nhạc Vũ khúc đàn gà con.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (4 phút)","gv":"- HS hát lại bài Trang trại vui vẻ để khởi động.","hs":"- HS hát khởi động."},{"ten":"B. KHÁM PHÁ - NGHE NHẠC (12 phút)","gv":"Mục tiêu: HS nghe và cảm nhận bản nhạc Vũ khúc đàn gà con.\n- GV giới thiệu bản nhạc Vũ khúc đàn gà con; cho HS nghe lần 1, hỏi cảm nhận về tốc độ, sắc thái (vui nhộn, ngộ nghĩnh).\n- Nghe lần 2 kết hợp vận động mô phỏng dáng đi của đàn gà con.\n- GV trò chuyện về nội dung, giáo dục HS yêu quý loài vật.","hs":"- HS nghe nhạc, nêu cảm nhận, vận động mô phỏng đàn gà con."},{"ten":"C. THỰC HÀNH - ÔN TẬP (11 phút)","gv":"Mục tiêu: HS ôn hát và ôn đọc nhạc.\n- Ôn bài Trang trại vui vẻ kết hợp gõ đệm, vận động phụ hoạ.\n- Ôn đọc nhạc số 4 với nhạc đệm; trình bày theo nhóm đọc, nhóm gõ, nhóm vận động.\n- GV nhận xét, hoàn thiện.","hs":"- HS ôn hát, ôn đọc nhạc; các nhóm trình bày và nhận xét lẫn nhau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở bản ghi hình buổi biểu diễn tác phẩm “Vũ khúc đàn gà con” để HS vừa nghe vừa nhìn thấy người nghệ sĩ đang chơi nhạc cụ nào, ngồi và cầm đàn ra sao; GV tạm dừng đúng lúc để HS chỉ lên màn hình gọi tên nhạc cụ vừa vang lên.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV cho HS đọc phần chú thích dưới đoạn phim: tên tác phẩm, tên tác giả, tên người biểu diễn; HS hiểu bản nhạc nào cũng do một người viết ra, nhắc đến bản nhạc thì phải gọi đúng tên người ấy.\n⚠ (Miền 4: An toàn) GV chọn và tải sẵn đoạn phim về “Vũ khúc đàn gà con” trước giờ học rồi mở ngoại tuyến để HS không nhìn thấy quảng cáo và các đoạn phim gợi ý bên cạnh; âm lượng để vừa nghe, HS ngồi cách màn hình vừa tầm mắt và không tự thao tác thiết bị.","hs":"- HS nghe và xem bản ghi hình “Vũ khúc đàn gà con”, gọi được tên nhạc cụ đang vang lên trên màn hình.\n- HS nói được tên tác phẩm và tên tác giả có ghi trong phần chú thích."},{"ten":"E. CỦNG CỐ - DẶN DÒ (2 phút)","gv":"- GV hệ thống lại nội dung tiết học, nhận xét tiết học (khen ngợi, nhắc nhở).\n- GV dặn HS về nhà ôn lại bài, tập biểu diễn cho người thân nghe, chuẩn bị bài tiết sau và làm bài trong vở bài tập (nếu có).","hs":"- HS lắng nghe, ghi nhớ.\n- HS hát/đọc nhạc lại một lần để kết thúc tiết học vui vẻ."}],"hotro":"","hoanhap":"","status":"checked","source":"KHBD Âm nhạc 2 KNTT — Bút Xanh (biên soạn tích hợp NLS + AI)"},
{"lop":2,"mon":"Âm nhạc","tuan":30,"tiet":30,"bai":"Chủ đề 7: Những con vật quanh em — Ôn tập chủ đề 7; Vận dụng – Sáng tạo","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Biểu diễn thuần thục bài Trang trại vui vẻ kết hợp gõ đệm, vận động; đọc thành thạo bài đọc nhạc số 4.\n- Củng cố nội dung chủ đề 7; tham gia trò chơi âm nhạc sáng tạo về loài vật.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động tập luyện, mạnh dạn thể hiện bài hát/bài đọc nhạc; tự điều chỉnh khi hát/gõ chưa đúng.\n- Giao tiếp và hợp tác: Biết hát, gõ đệm, vận động theo nhóm; lắng nghe và phối hợp nhịp nhàng cùng bạn.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm hoặc ý tưởng biểu diễn đơn giản.\n3. Phẩm chất\n- Chăm chỉ, hợp tác, tự tin biểu diễn.\n- Chăm chỉ: Tích cực tham gia các hoạt động ca hát, đọc nhạc, trò chơi âm nhạc.\n- Yêu thích môn Âm nhạc; cảm nhận được vẻ đẹp của âm thanh.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ cơ bản (thanh phách, song loan, trống con, ma-ra-cát).\n- HS: SGK Âm nhạc 2 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ cơ bản (thanh phách, song loan) nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (4 phút)","gv":"- Trò chơi nghe giai điệu đoán tên bài hát, bài đọc nhạc đã học trong chủ đề.","hs":"- HS lắng nghe và đoán tên bài hát/bài đọc nhạc."},{"ten":"B. THỰC HÀNH - ÔN TẬP (14 phút)","gv":"Mục tiêu: HS ôn hát và ôn đọc nhạc.\n- HS biểu diễn bài Trang trại vui vẻ kết hợp gõ đệm, vận động phụ hoạ theo nhóm.\n- Ôn đọc nhạc số 4 với nhạc đệm ở các hình thức nhóm đọc, nhóm gõ, nhóm vận động.\n- GV nhận xét, tuyên dương.","hs":"- HS ôn hát, ôn đọc nhạc; các nhóm biểu diễn và nhận xét lẫn nhau."},{"ten":"C. VẬN DỤNG - SÁNG TẠO (10 phút)","gv":"Mục tiêu: HS sáng tạo động tác mô phỏng loài vật.\n- HS tự nghĩ và biểu diễn vài động tác mô phỏng các con vật phụ hoạ cho bài hát.\n- Tổ chức thi biểu diễn nhóm; khen ngợi ý tưởng sáng tạo.","hs":"- HS sáng tạo động tác, luyện tập trong nhóm và lên biểu diễn."},{"ten":"E. CỦNG CỐ - DẶN DÒ (2 phút)","gv":"- GV hệ thống lại nội dung tiết học, nhận xét tiết học (khen ngợi, nhắc nhở).\n- GV dặn HS về nhà ôn lại bài, tập biểu diễn cho người thân nghe, chuẩn bị bài tiết sau và làm bài trong vở bài tập (nếu có).","hs":"- HS lắng nghe, ghi nhớ.\n- HS hát/đọc nhạc lại một lần để kết thúc tiết học vui vẻ."}],"hotro":"","hoanhap":"","status":"checked","source":"KHBD Âm nhạc 2 KNTT — Bút Xanh (biên soạn tích hợp NLS + AI)"},
{"lop":2,"mon":"Âm nhạc","tuan":31,"tiet":31,"bai":"Chủ đề 8: Mùa hè vui — Học hát: Ngày hè vui (Nhạc và lời: Lê Bùi)","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Hát đúng giai điệu, thuộc lời ca bài Ngày hè vui; thể hiện tính chất vui tươi, rộn ràng của bài hát.\n- Biết hát kết hợp gõ đệm theo phách, theo nhịp.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động tập luyện, mạnh dạn thể hiện bài hát/bài đọc nhạc; tự điều chỉnh khi hát/gõ chưa đúng.\n- Giao tiếp và hợp tác: Biết hát, gõ đệm, vận động theo nhóm; lắng nghe và phối hợp nhịp nhàng cùng bạn.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm hoặc ý tưởng biểu diễn đơn giản.\n3. Phẩm chất\n- Nhân ái, lạc quan: Yêu thiên nhiên, vui tươi, giữ an toàn trong những ngày hè.\n- Chăm chỉ: Tích cực tham gia các hoạt động ca hát, đọc nhạc, trò chơi âm nhạc.\n- Yêu thích môn Âm nhạc; cảm nhận được vẻ đẹp của âm thanh.\n4. Tích hợp\n- Năng lực số 1.1 CB1 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS nghe bản thu mẫu và hát đúng lời, đúng cao độ bài “Ngày hè vui”.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ cơ bản (thanh phách, song loan, trống con, ma-ra-cát).\n- HS: SGK Âm nhạc 2 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ cơ bản (thanh phách, song loan) nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (5 phút)","gv":"- GV giới thiệu chủ đề Mùa hè vui; cho HS xem tranh cảnh mùa hè (thả diều, bơi lội, sinh hoạt hè).\n- Trò chơi: kể tên các hoạt động vui chơi mùa hè mà em thích.","hs":"- HS quan sát tranh, kể tên hoạt động mùa hè; tham gia trò chơi vui vẻ."},{"ten":"B. KHÁM PHÁ - HỌC HÁT (15 phút)","gv":"Mục tiêu: HS hát đúng bài Ngày hè vui.\n- GV giới thiệu bài hát của nhạc sĩ Lê Bùi, nói về niềm vui của các bạn nhỏ khi mùa hè đến sau một năm học.\n- GV hát mẫu (hoặc mở file); hỏi cảm nhận về tính chất bài hát (vui tươi, rộn ràng).\n- Hướng dẫn đọc lời ca theo tiết tấu, chia câu; dạy hát nối tiếp từng câu; luyện hát cho thuộc.","hs":"- HS nghe hát mẫu, nêu cảm nhận.\n- HS đọc lời ca, học hát từng câu, luyện hát cho thuộc."},{"ten":"C. THỰC HÀNH - LUYỆN TẬP (10 phút)","gv":"Mục tiêu: HS hát kết hợp gõ đệm theo phách.\n- GV hát và gõ đệm mẫu theo phách.\n- HS hát kết hợp gõ đệm theo phách với các hình thức tập thể, tổ, cá nhân.\n- GV nhận xét, sửa sai; giáo dục HS giữ an toàn khi vui chơi trong hè.","hs":"- HS hát + gõ đệm theo phách; các tổ, cá nhân thực hiện."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở bản thu mẫu bài “Ngày hè vui” lấy từ học liệu điện tử của bộ sách hoặc kênh chính thức của nhà xuất bản, phóng màn hình để cả lớp nhìn thấy tên bài hát, chỉ cho HS dòng ghi tác giả “Nhạc và lời: Lê Bùi”; GV mở từng câu, tạm dừng cho HS nghe kĩ rồi hát theo, câu nào HS hát chênh cao độ thì GV mở lại đúng câu đó.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV dùng điện thoại thu âm phần hát bài “Ngày hè vui” của cả lớp rồi mở lại ngay cho HS nghe; HS chỉ ra chỗ mình hát to quá, nhỏ quá hoặc sai lời — nghe lại giọng của chính mình là điều hát chay không có được. GV thao tác thiết bị, HS nghe và nhận xét.\n⚠ (Miền 4: An toàn) Bản thu bài “Ngày hè vui” chỉ lấy từ học liệu của bộ sách hoặc kênh chính thức, không tải nhạc từ trang lạ vì có thể sai lời, sai nhạc và kèm quảng cáo không phù hợp; giới thiệu bài hát phải nói rõ tên tác giả; mở loa vừa đủ nghe, không để loa sát tai HS.","hs":"- HS nghe bản thu mẫu và hát đúng lời, đúng cao độ bài “Ngày hè vui”.\n- HS nói được tên bài hát cùng tên tác giả; nghe lại bản thu của lớp và chỉ ra một chỗ cần sửa."},{"ten":"E. CỦNG CỐ - DẶN DÒ (2 phút)","gv":"- GV hệ thống lại nội dung tiết học, nhận xét tiết học (khen ngợi, nhắc nhở).\n- GV dặn HS về nhà ôn lại bài, tập biểu diễn cho người thân nghe, chuẩn bị bài tiết sau và làm bài trong vở bài tập (nếu có).","hs":"- HS lắng nghe, ghi nhớ.\n- HS hát/đọc nhạc lại một lần để kết thúc tiết học vui vẻ."}],"hotro":"","hoanhap":"","status":"checked","source":"KHBD Âm nhạc 2 KNTT — Bút Xanh (biên soạn tích hợp NLS + AI)"},
{"lop":2,"mon":"Âm nhạc","tuan":32,"tiet":32,"bai":"Chủ đề 8: Mùa hè vui — Ôn tập bài hát: Ngày hè vui; Nhạc cụ: Dùng nhạc cụ gõ thể hiện hình tiết tấu","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Hát thuộc bài Ngày hè vui; hát kết hợp gõ đệm và vận động phụ hoạ.\n- Biết dùng các nhạc cụ gõ (thanh phách, song loan, trống con, ma-ra-cát) thể hiện đúng hình tiết tấu và gõ đệm cho bài hát.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động tập luyện, mạnh dạn thể hiện bài hát/bài đọc nhạc; tự điều chỉnh khi hát/gõ chưa đúng.\n- Giao tiếp và hợp tác: Biết hát, gõ đệm, vận động theo nhóm; lắng nghe và phối hợp nhịp nhàng cùng bạn.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm hoặc ý tưởng biểu diễn đơn giản.\n3. Phẩm chất\n- Chăm chỉ, hợp tác.\n- Chăm chỉ: Tích cực tham gia các hoạt động ca hát, đọc nhạc, trò chơi âm nhạc.\n- Yêu thích môn Âm nhạc; cảm nhận được vẻ đẹp của âm thanh.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ cơ bản (thanh phách, song loan, trống con, ma-ra-cát).\n- HS: SGK Âm nhạc 2 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ cơ bản (thanh phách, song loan) nếu có.\n- Nhạc cụ gõ: thanh phách, song loan, trống con, ma-ra-cát.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (4 phút)","gv":"- HS hát lại bài Ngày hè vui để khởi động.","hs":"- HS hát khởi động."},{"ten":"B. THỰC HÀNH - ÔN TẬP BÀI HÁT (11 phút)","gv":"Mục tiêu: HS ôn hát và vận động phụ hoạ.\n- HS ôn bài Ngày hè vui với nhạc đệm, kết hợp vận động phụ hoạ rộn ràng.\n- Trình bày theo nhóm hát, nhóm gõ, nhóm vận động; GV nhận xét.","hs":"- HS ôn hát, vận động phụ hoạ; trình bày theo nhóm."},{"ten":"C. KHÁM PHÁ - NHẠC CỤ GÕ THỂ HIỆN HÌNH TIẾT TẤU (13 phút)","gv":"Mục tiêu: HS dùng nhạc cụ gõ thể hiện hình tiết tấu.\n- GV giới thiệu hình tiết tấu; đọc mẫu và gõ mẫu bằng thanh phách; HS đọc và gõ theo.\n- HS luyện gõ tiết tấu bằng thanh phách, song loan, trống con, ma-ra-cát.\n- Dùng nhạc cụ gõ gõ đệm cho bài Ngày hè vui; chia nhóm hoà tấu; GV sửa sai.","hs":"- HS đọc và gõ hình tiết tấu bằng nhiều nhạc cụ; gõ đệm cho bài hát và hoà tấu theo nhóm."},{"ten":"E. CỦNG CỐ - DẶN DÒ (2 phút)","gv":"- GV hệ thống lại nội dung tiết học, nhận xét tiết học (khen ngợi, nhắc nhở).\n- GV dặn HS về nhà ôn lại bài, tập biểu diễn cho người thân nghe, chuẩn bị bài tiết sau và làm bài trong vở bài tập (nếu có).","hs":"- HS lắng nghe, ghi nhớ.\n- HS hát/đọc nhạc lại một lần để kết thúc tiết học vui vẻ."}],"hotro":"","hoanhap":"","status":"checked","source":"KHBD Âm nhạc 2 KNTT — Bút Xanh (biên soạn tích hợp NLS + AI)"},
{"lop":2,"mon":"Âm nhạc","tuan":33,"tiet":33,"bai":"Chủ đề 8: Mùa hè vui — Nghe nhạc: Mùa hè ước mong; Vận dụng – Sáng tạo","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Chăm chú nghe và biểu hiện cảm xúc khi nghe bài Mùa hè ước mong; nêu được cảm nhận về tính chất bài hát.\n- Vận dụng hát, gõ đệm, vận động sáng tạo theo bài hát đã học.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động tập luyện, mạnh dạn thể hiện bài hát/bài đọc nhạc; tự điều chỉnh khi hát/gõ chưa đúng.\n- Giao tiếp và hợp tác: Biết hát, gõ đệm, vận động theo nhóm; lắng nghe và phối hợp nhịp nhàng cùng bạn.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm hoặc ý tưởng biểu diễn đơn giản.\n3. Phẩm chất\n- Nhân ái, lạc quan: Yêu thiên nhiên, vui tươi, giữ an toàn trong những ngày hè.\n- Chăm chỉ: Tích cực tham gia các hoạt động ca hát, đọc nhạc, trò chơi âm nhạc.\n- Yêu thích môn Âm nhạc; cảm nhận được vẻ đẹp của âm thanh.\n4. Tích hợp\n- Năng lực số 1.1 CB1 (Duyệt, tìm kiếm và lọc dữ liệu, thông tin, nội dung số): HS nghe và xem bản ghi hình “Mùa hè ước mong”, gọi được tên nhạc cụ đang vang lên trên màn hình.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ cơ bản (thanh phách, song loan, trống con, ma-ra-cát).\n- HS: SGK Âm nhạc 2 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ cơ bản (thanh phách, song loan) nếu có.\n- File bài nghe nhạc Mùa hè ước mong.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (4 phút)","gv":"- HS hát lại bài Ngày hè vui kết hợp gõ đệm để khởi động.","hs":"- HS hát và gõ đệm khởi động."},{"ten":"B. KHÁM PHÁ - NGHE NHẠC (12 phút)","gv":"Mục tiêu: HS nghe và cảm nhận bài Mùa hè ước mong.\n- GV giới thiệu bài hát; cho HS nghe lần 1, hỏi cảm nhận về tốc độ, sắc thái (vui tươi, trong sáng).\n- Nghe lần 2 kết hợp vận động nhịp nhàng theo bài.\n- GV trò chuyện về nội dung, gợi ý HS chia sẻ ước mong của mình trong mùa hè.","hs":"- HS nghe nhạc, nêu cảm nhận, vận động nhịp nhàng; chia sẻ ước mong mùa hè."},{"ten":"C. VẬN DỤNG - SÁNG TẠO (11 phút)","gv":"Mục tiêu: HS vận dụng hát, gõ đệm, vận động sáng tạo.\n- HS ôn bài Ngày hè vui kết hợp gõ đệm và tự nghĩ vài động tác phụ hoạ đơn giản.\n- Tổ chức biểu diễn theo nhóm; GV khen ngợi ý tưởng sáng tạo.","hs":"- HS sáng tạo động tác, luyện tập và biểu diễn theo nhóm."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở bản ghi hình buổi biểu diễn tác phẩm “Mùa hè ước mong” để HS vừa nghe vừa nhìn thấy người nghệ sĩ đang chơi nhạc cụ nào, ngồi và cầm đàn ra sao; GV tạm dừng đúng lúc để HS chỉ lên màn hình gọi tên nhạc cụ vừa vang lên.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV cho HS đọc phần chú thích dưới đoạn phim: tên tác phẩm, tên tác giả, tên người biểu diễn; HS hiểu bản nhạc nào cũng do một người viết ra, nhắc đến bản nhạc thì phải gọi đúng tên người ấy.\n⚠ (Miền 4: An toàn) GV chọn và tải sẵn đoạn phim về “Mùa hè ước mong” trước giờ học rồi mở ngoại tuyến để HS không nhìn thấy quảng cáo và các đoạn phim gợi ý bên cạnh; âm lượng để vừa nghe, HS ngồi cách màn hình vừa tầm mắt và không tự thao tác thiết bị.","hs":"- HS nghe và xem bản ghi hình “Mùa hè ước mong”, gọi được tên nhạc cụ đang vang lên trên màn hình.\n- HS nói được tên tác phẩm và tên tác giả có ghi trong phần chú thích."},{"ten":"E. CỦNG CỐ - DẶN DÒ (2 phút)","gv":"- GV hệ thống lại nội dung tiết học, nhận xét tiết học (khen ngợi, nhắc nhở).\n- GV dặn HS về nhà ôn lại bài, tập biểu diễn cho người thân nghe, chuẩn bị bài tiết sau và làm bài trong vở bài tập (nếu có).","hs":"- HS lắng nghe, ghi nhớ.\n- HS hát/đọc nhạc lại một lần để kết thúc tiết học vui vẻ."}],"hotro":"","hoanhap":"","status":"checked","source":"KHBD Âm nhạc 2 KNTT — Bút Xanh (biên soạn tích hợp NLS + AI)"},
{"lop":2,"mon":"Âm nhạc","tuan":34,"tiet":34,"bai":"Ôn tập cuối năm (Tiết 1)","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Hát thuộc, biểu diễn được các bài hát đã học ở học kì II: Hoa lá mùa xuân, Mẹ ơi có biết, Trang trại vui vẻ, Ngày hè vui.\n- Đọc được bài đọc nhạc số 3, số 4; nhận biết các nhạc cụ đã học (ma-ra-cát và các nhạc cụ đã giới thiệu).\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động tập luyện, mạnh dạn thể hiện bài hát/bài đọc nhạc; tự điều chỉnh khi hát/gõ chưa đúng.\n- Giao tiếp và hợp tác: Biết hát, gõ đệm, vận động theo nhóm; lắng nghe và phối hợp nhịp nhàng cùng bạn.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm hoặc ý tưởng biểu diễn đơn giản.\n3. Phẩm chất\n- Chăm chỉ, tự tin biểu diễn.\n- Chăm chỉ: Tích cực tham gia các hoạt động ca hát, đọc nhạc, trò chơi âm nhạc.\n- Yêu thích môn Âm nhạc; cảm nhận được vẻ đẹp của âm thanh.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ cơ bản (thanh phách, song loan, trống con, ma-ra-cát).\n- HS: SGK Âm nhạc 2 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ cơ bản (thanh phách, song loan) nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (4 phút)","gv":"- Trò chơi nghe giai điệu đoán tên bài hát các bài đã học trong học kì II.","hs":"- HS lắng nghe và đoán tên bài hát."},{"ten":"B. THỰC HÀNH - ÔN TẬP BÀI HÁT (14 phút)","gv":"Mục tiêu: HS ôn và biểu diễn các bài hát học kì II.\n- HS ôn lần lượt các bài hát đã học, kết hợp gõ đệm và vận động.\n- Chia nhóm biểu diễn từng bài; GV nhận xét, sửa sai.","hs":"- HS ôn hát, gõ đệm, vận động; các nhóm biểu diễn."},{"ten":"C. THỰC HÀNH - ÔN ĐỌC NHẠC & NHẠC CỤ (10 phút)","gv":"Mục tiêu: HS ôn đọc nhạc và nhận biết nhạc cụ.\n- Ôn bài đọc nhạc số 3, số 4 kết hợp kí hiệu bàn tay, nhạc đệm.\n- Ôn nhận biết các nhạc cụ đã học qua hình ảnh/âm thanh.","hs":"- HS ôn đọc nhạc; nhận biết nhạc cụ."},{"ten":"E. CỦNG CỐ - DẶN DÒ (2 phút)","gv":"- GV hệ thống lại nội dung tiết học, nhận xét tiết học (khen ngợi, nhắc nhở).\n- GV dặn HS về nhà ôn lại bài, tập biểu diễn cho người thân nghe, chuẩn bị bài tiết sau và làm bài trong vở bài tập (nếu có).","hs":"- HS lắng nghe, ghi nhớ.\n- HS hát/đọc nhạc lại một lần để kết thúc tiết học vui vẻ."}],"hotro":"","hoanhap":"","status":"checked","source":"KHBD Âm nhạc 2 KNTT — Bút Xanh (biên soạn tích hợp NLS + AI)"},
{"lop":2,"mon":"Âm nhạc","tuan":35,"tiet":35,"bai":"Ôn tập, đánh giá cuối năm (Tiết 2)","yccd":"1. Năng lực âm nhạc (đặc thù)\n- Biểu diễn tự tin một bài hát tự chọn ở học kì II kết hợp gõ đệm hoặc vận động; đọc được một bài đọc nhạc.\n- Tự đánh giá và đánh giá bạn về khả năng ca hát, đọc nhạc, gõ đệm.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động tập luyện, mạnh dạn thể hiện bài hát/bài đọc nhạc; tự điều chỉnh khi hát/gõ chưa đúng.\n- Giao tiếp và hợp tác: Biết hát, gõ đệm, vận động theo nhóm; lắng nghe và phối hợp nhịp nhàng cùng bạn.\n- Giải quyết vấn đề và sáng tạo: Bước đầu nghĩ ra động tác vận động, cách gõ đệm hoặc ý tưởng biểu diễn đơn giản.\n3. Phẩm chất\n- Chăm chỉ, tự tin, trung thực khi tự đánh giá.\n- Chăm chỉ: Tích cực tham gia các hoạt động ca hát, đọc nhạc, trò chơi âm nhạc.\n- Yêu thích môn Âm nhạc; cảm nhận được vẻ đẹp của âm thanh.\n4. Tích hợp\n- Năng lực số 3.2 CB1 (Tích hợp và tinh chỉnh nội dung số): HS xem lại đoạn phim phần biểu diễn của tổ và chỉ ra được một chỗ cần sửa.","dodung":"- GV: Máy tính, ti vi/máy chiếu, loa; bài giảng điện tử có file âm thanh, video, hình ảnh minh hoạ; đàn phím điện tử (organ); nhạc cụ gõ cơ bản (thanh phách, song loan, trống con, ma-ra-cát).\n- HS: SGK Âm nhạc 2 (Kết nối tri thức với cuộc sống), vở ghi, đồ dùng học tập; nhạc cụ gõ cơ bản (thanh phách, song loan) nếu có.","hoatdong":[{"ten":"A. KHỞI ĐỘNG (4 phút)","gv":"- GV nêu yêu cầu tiết đánh giá; cho HS hát khởi động một bài đã học.","hs":"- HS hát khởi động, nắm yêu cầu đánh giá."},{"ten":"B. THỰC HÀNH - BIỂU DIỄN ĐÁNH GIÁ (16 phút)","gv":"Mục tiêu: HS biểu diễn để GV đánh giá cuối năm.\n- GV tổ chức cho HS (cá nhân/nhóm) biểu diễn một bài hát tự chọn kết hợp gõ đệm hoặc vận động.\n- Mời một số HS đọc một bài đọc nhạc theo kí hiệu bàn tay.\n- GV quan sát, ghi nhận mức độ đạt được của từng HS.","hs":"- HS biểu diễn bài hát, đọc nhạc; các bạn lắng nghe, cổ vũ."},{"ten":"C. VẬN DỤNG - ĐÁNH GIÁ (10 phút)","gv":"Mục tiêu: HS tự đánh giá và đánh giá bạn.\n- GV hướng dẫn HS tự nhận xét phần biểu diễn của mình và của bạn (đúng giai điệu, gõ đệm đều, tự tin).\n- GV tổng kết cả năm học, khen ngợi, động viên HS giữ tình yêu âm nhạc trong dịp hè.","hs":"- HS tự đánh giá và nhận xét bạn; lắng nghe tổng kết của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV quay lại phần biểu diễn cuối năm học của từng tổ rồi mở lên màn hình cho cả lớp xem; HS chỉ ra chỗ tổ mình hát đều, chỗ vào chưa cùng lúc và nói mình sẽ sửa thế nào nếu được hát lại.\n- (Miền 6: Ứng dụng trí tuệ nhân tạo — Cơ bản, bậc 1) GV mở cho HS nghe hai đoạn nhạc ngắn cùng một giai điệu: một đoạn do nghệ sĩ hát, một đoạn do máy tự tạo ra. HS đoán đoạn nào do người hát và nói vì sao mình nghĩ vậy; GV giải thích máy làm theo những bản nhạc nó đã học nên hát rất đều nhưng chưa có hơi thở và tình cảm của người hát. GV thao tác hoàn toàn, HS chỉ nghe và trả lời.\n⚠ (Miền 4: An toàn) Đoạn phim quay lớp chỉ mở trong giờ học và trong buổi họp phụ huynh khi cả lớp đồng ý, không đăng lên mạng, không gửi cho người ngoài; bạn nào không muốn bị quay thì GV không quay; nhận xét bạn bằng lời tử tế, không chê bai hình dáng hay giọng hát của bạn.","hs":"- HS xem lại đoạn phim phần biểu diễn của tổ và chỉ ra được một chỗ cần sửa.\n- HS trả lời đúng bộ câu hỏi ôn tập và gọi được tên bài hát, tên tác giả đã học."},{"ten":"E. CỦNG CỐ - DẶN DÒ (2 phút)","gv":"- GV hệ thống lại nội dung tiết học, nhận xét tiết học (khen ngợi, nhắc nhở).\n- GV dặn HS về nhà ôn lại bài, tập biểu diễn cho người thân nghe, chuẩn bị bài tiết sau và làm bài trong vở bài tập (nếu có).","hs":"- HS lắng nghe, ghi nhớ.\n- HS hát/đọc nhạc lại một lần để kết thúc tiết học vui vẻ."}],"hotro":"","hoanhap":"","status":"checked","source":"KHBD Âm nhạc 2 KNTT — Bút Xanh (biên soạn tích hợp NLS + AI)"}
];
